export const AI_REEL_EXAMPLES: readonly { id: string; f: 'fidit' | 'igrat' | 'solo'; r: 'g' | 'r' | 'a'; title: string; t: string }[] = [{"id":"uchu-fidit-manifest","f":"fidit","r":"r","title":"Манифест / вводный выпуск рубрики","t":"Устал поднимать ПТС, постоянно топ нетворкс и фул слоты к сороковой минуте. Тебя утомляют одни победы, и ты хочешь почувствовать запах свободы и лустрика? А возможно, у тебя слишком высокая поряда и ты никогда не был в ЛП, тогда эта рубрика для тебя. Я научу тебя правильно пиздить крипов у своего Керри. Как сделать, чтобы твой мидер сломал шмотки. Мы доведём тимейтов до нервного срыва, и девять репортов гарантированно войдут в твою жопу по самые яйца. Мои секретные техники Фидо разрабатывались в говне и моче, и они помогут тебе спуститься как минимум до первого рекрута. И ты наконец почувствуешь запах сгущёнки, но рано открывать рот, ведь нам предстоит много работы. Ведь дорога будет тяжёлая, видеть это вам не рапа делать. Тут нужно выработать анстилл высшего уровня. Мы начнём оттачивать наши навыки уже в следующей части."},{"id":"uchu-fidit-draft","f":"fidit","r":"g","title":"Как правильно драфтить в доте?","t":"Как правильно драфтить в доте? Сегодня разберём лучших саппортов для нашего пика. Многие думают, что от саппорта нужен контроль, сейф и помощь на линии. Очередная чепуха, которую нам вбили в голову игроки на Керри. Вас могут попросить взять таких героев, как Виверн, Бич Доктор, Белка и этих всех однокнопочных бездарных героев. Но тут главное — не сломаться. Ведь эсэс, антимаг, морф или Хускар — это именно те саппорты, которые дадут понять всем, что вы серьёзный человек. Вы не ведётесь на меду, вы привыкли брать всё в свои руки. Вы не подстраиваетесь под команду. Эта команда должна научиться играть вокруг вас. Будет тяжело, маты, крики и куча репортов полетят в ваш адрес. Но мы только начинаем отращивать наши яички. Ведь неважно, как вы выигрываете. Важно, насколько красиво вы проиграете."},{"id":"uchu-fidit-wards","f":"fidit","r":"g","title":"Как правильно ставить варды?","t":"Как правильно ставить варды? Первое правило — игнорируем все первые просьбы команды. Покупаем вар только тогда, когда союзники уже начинают злиться и орать. В идеале нужно протянуть ещё немного, чтобы они не выдержали и купили его за тебя. Но если тебе всё-таки пришлось потратить свои деньги, то варт обязательно должен стать причиной твоей смерти во время установки. Но ты ведь тоже почувствовал слабость. Почему ты тратишь свои деньги, когда твой Керри купается в них? Поэтому у настоящего саппорта всегда включена специальная функция, которая удаляет стандартные варды из доты и вместо них оставляет один новый улучшенный вар. Да, он стоит немного дороже, но поверь, он того стоит. Поэтому в следующий раз, когда команда попросит тебя купить вар, не нужно спорить и что-то объяснять. Просто добавляешь новый вард в бай и начинаешь копить свои 420. А о том, как быстрее собрать деньги на свой первый Вард, мы поговорим уже в следующем видео."},{"id":"uchu-fidit-lane","f":"fidit","r":"a","title":"Как никогда не проигрывать свою линию?","t":"Как никогда не проигрывать свою линию? У каждого из вас бывало, что невозможно стоять на линии. Вас душат со всех сторон, а игра постепенно выходит из-под контроля. Здесь самое главное — не паниковать и не наделать ошибок. Для начала находим линию, которую ваша команда уже выигрывает. И отправляемся туда. Но идти пешком нельзя, ведь время — это ресурс. Поэтому просто умираем и уже от фонтана телепортируемся. Но вот незадача, линия-то занята. Не проблема. Просто говорим Тимейту, чтобы он съебался нахуй с неё, потому что всю игру портят. Не приходит гангать, не покупает ресурсы и вообще занимается непонятно чем, и совершенно неважно, какая у него роль. Но что делать, если ваша команда проиграла все три линии? Заходи в телегу, скидывай свой лучший фит, и я его разберу. Здесь всё ещё проще. У противников есть сразу три выигранные линии. Выбираем любую и идём туда. Я учу вас мыслить нестандартно, даже в самых критических ситуациях, ведь невозможно проиграть линию, если каждый раз переходить на ту, которая выигрывает."},{"id":"uchu-fidit-support-money","f":"fidit","r":"g","title":"Откуда бедному сапорту брать деньги?","t":"Откуда бедному саппорту брать деньги? Ну, бедный тут только ты, поэтому лови несколько надёжных способов поднять бабла. Керри получает фарм только потому, что ты позволяешь ему спокойно бить крипов. Поэтому каждого второго крипа забирай себе. И это твоя законная комиссия за поддержку Линии. Если Керри промахнулся по крипу, тоже забирай. Деньги не должны пропадать только потому, что он плохо выполняет свою работу. Со стаками всё ещё проще. Кто их сделал, тому они и принадлежат. Ждёшь, пока Керри оставит крипам немного здоровья, а затем одной способностью забираешь весь лагерь. Это называется эффективная командная работа. И самое главное — не трать заработанные на дешёвые расходники. Всю игру ты должен чётко следовать своему финансовому плану, ни одной монеты на команду. А если Керри спросит, куда делись все его крипы? Просто укажи на свои предметы. Пусть видит, что деньги не пропали, они были грамотно инвестированы."},{"id":"uchu-fidit-carry90","f":"fidit","r":"a","title":"90% керри совершают одну ошибку","t":"90% керри совершают одну ошибку, они приходят в драку. Сейчас объясню. Твоя команда дерётся не потому, что ей нужна твоя помощь, она просто пытается отвлечь тебя от фарма. Пока на карте остался хотя бы один крип, ты не имеешь права откликаться на какие-то там командные проблемы. Особенно, если до следующего предмета осталось всего 3 500 золота. Ты уже практически его собрал, поэтому сейчас вообще нельзя отвлекаться. В драке ты можешь умереть, а мёртвый керри, как известно, не фармит. Поэтому просто продолжай заниматься своими делами. Если команда выиграла вчетвером, значит ты грамотно создал им пространство. А если проиграла, ну и правильно, что не пошёл. С такой командой там всё равно делать было нечего. И вот наконец, на сороковой минуте, настоящий Керри выходит из леса с одним сапогом и долгожданным БФ. Чтобы показать, кто здесь папочка. Только не пугайся, если к этому моменту уже горит трон. Причём неважно чей. Пока на карте есть крипы, у тебя есть дела поважнее. Запомни, хороший Керри не опаздывает в драку. Он приходит ровно тогда, когда там уже нечего делать."},{"id":"uchu-fidit-bkb","f":"fidit","r":"g","title":"Почему нельзя покупать БКБ?","t":"БКБ покупают только те, кто не умеет играть в Доту! Ты вообще представляешь, сколько урона можно купить на четыре тысячи золота? А БКБ что даёт? Несколько секунд, в течение которых тебя даже нормально побить не могут. И за это ты должен платить?! Особенно бесят люди, которые советуют покупать БКБ против пяти станов. То есть враги специально взяли героев с контролем, прокачали способности, придумали комбинацию, а ты хочешь одной кнопкой испортить им всю игру? Имей хоть какое-то уважение к чужому труду! И вообще, зачем тебе БКБ, если у тебя в команде четыре человека? Пусть саппорты покупают Глиммеры, Форсы, Лотусы и спасают тебя. А если не спасли — значит, плохо выполняют свою работу. Ты керри! Твоя задача — наносить урон, а не думать о том, как выжить. И запомни: если ты купил БКБ и умер — виноват ты. А если не купил — виновата команда. Поэтому хороший керри никогда не покупает БКБ!"},{"id":"uchus-igrat-01","f":"igrat","r":"r","title":"Начало пути — первый выпуск","t":"Учусь играть в Доту! Все свои старческие годы мне удавалось игнорировать доту. Я держался до последнего, но всё-таки сдался. И эта игра меня втянула. Около двадцати матчей позади, а впереди бесконечные репорты, маты и знакомства с прекрасными людьми в чате. Узнав, что я продолжил играть в Доту, меня бросил парень. И двое отцов со мной не разговаривают. И думаете, я сдался? Наоборот. С этого дня я буду ежедневно выкладывать свой путь обучения максимально честно, со всеми тупейшими фейлами, позорными закупами и попытками хоть чему-то научиться. Сначала я выбрал мид, но быстро понял, что сильно погорячился, и я встал на путь саппорта. Мне понравилась четвёртая позиция, она как надоедливая муха. Понимаете, о чём я, да? Из героев мне много кто понравился, и, конечно, хочется пощупать каждого. И поэтому подписывайтесь, если хочешь посмотреть, как дота ломает человека."},{"id":"uchus-igrat-02","f":"igrat","r":"r","title":"Стаки и отводы","t":"Учусь играть в Доту! Оказывается, мало просто стоять на линии, пока тимейты пробивают фуза. Нужно ещё делать стаки и отводы. Со стаками вроде всё понятно. Ждём пятьдесят пятую секунду, бьём лесного крепа и бежим подальше. В идеале, если получится стакнуть сразу два кэмпа. За такое тебя сам Габен благословит. С отводами всё сложнее. До этого меня только за гаражи отводили коллекцию пиздячек показывать. Но схема очень похожая. Только тебе постоянно будет мешать такой же подсос, как и ты. Вражеский саппорт спит и видит, как бы испортить тебе жизнь, то крипов твоих переагрит, то тебя в лесу отпиздячит. Итоги дня таковы: пытаемся стакать и отводить. Тайминги в голове, жопа в огне. Завтра попробую не фидить как тварь. Подпишись. Заебал."},{"id":"uchus-igrat-03","f":"igrat","r":"r","title":"Ливеры","t":"Учусь играть в Доту! Объясните, нубы, что это за странный ритуал с ливерами? Блядь, что это за слово вообще? Ливеры. Почти в каждой второй катке один чел, неважно из какой команды, просто ливает. Проходит время, и система пишет: «Всё, пацаны, расходимся. Можно спокойно покидать игру, ваши жопы будут целы, наказания не будет». И люди реально выходят, и я сам выхожу. Ведь какой смысл сидеть дальше? Но иногда я оставался просто поиграть, потому что игра хорошо шла. Или просто потренироваться. И тот самый чувак, который первый ли вал вдруг возвращается, заходит и начинает, как ни в чём не бывало, нормально играть, общаться в чате даже. Зачем? Может, в этом есть какой-то секретный смысл, который мой тупой мозг не догоняет? Объясните в комментах, что это за мувы такие. И подпишись. Заебал."},{"id":"uchus-igrat-04","f":"igrat","r":"r","title":"Аппарат","t":"Учусь играть в доту! Я поиграл на аппарате «Три игры». Кто не в курсе, я сейчас пробую разных героев по вашим советам в поисках своей сигнатурки. Отчёт по каждому матчу можете посмотреть у меня в Телеграме. Этот мужик просто пушка! Дальность атаки пиздец какая. Стоишь в стратосфере за спинами союзников и на чиле раскидываешь кнопки. Враги тебя даже не видят, а лица у них отлетают. Ульта — это кайф. Наводишь суету на другом конце карты, пока сам отдыхаешь на фонтане. Но для четвёрки как будто он спорный. Если ты приходишь гангать мид, а у врага есть хоть какой-то эскеп или просто быстрые ноги, то он просто убежит и план «Капкан провалин». Аппарат получает медаль Золотого Габена. Дальше я планирую поиграть на тини. Посмотрим, на что способен этот каменный мужик. И подпишись. Заебал."},{"id":"uchus-igrat-05","f":"igrat","r":"r","title":"Инвокер","t":"Учусь играть в доту! Инвокер — герой, который не прощает халтуры, так что пришло время серьёзно попотеть. И я сейчас даже не про пальцы, а про мозг. Хотя будем честны, он у меня сейчас где-то в глубоком отпуске. Если на Тини я просто не попадал тоссом, то здесь мои пальцы превращаются в полный хаос, способностей столько, что пока я вспоминаю, в каком порядке всё нажимать, враг думает, что я просто АФК или завис. План у меня простой. Сейчас смотрю гайды и заучиваю комбинации, следом немного пробую с ботами, но и самое сладкое — дуруинить катки. Так что, если ты увидишь инвокера, который просто стоит, не бей. Это я пытаюсь вспомнить, где у него кнопка победить. И подпишись. Заебал."},{"id":"uchus-igrat-06","f":"igrat","r":"r","title":"Белка","t":"Учусь играть в Доту! Я всегда знал, что у меня белка, но не думал, что когда-нибудь сяду за неё играть. Герой сначала показался суперпростым: кинул орех, завязал, ультой стрельнул и убегаешь, пока жопу не порвали. Но на деле всё не так, кроме последнего пункта. Гангать линии на ней очень приятно. Включаешь смок и просто ниоткуда появляешься и связываешь противника. Но если запахло жареной белкой, включаешь третий скилл и мчимся под деревьями подальше от этой заварушки, которую сам и начал. Ульта, на мой взгляд, самый сильный и сложный скилл, ведь тут главное не промахнуться. Но вы понимаете, что я пока на такое не способен. Но, сидя в кустах, ты целишься, и вот летит моя стрела, смазанная белычьим говном, а противник отходит на сантиметр в сторону, и можно начинать плакать. Депрессия на неделю гарантирована. К сожалению, герой часто в бане, и хотелось больше на нём отыграть, конечно, ибо он суперкайфовый. Наша белка занимает золотого Габена под цвет своих орешков. Ну а дальше вы проголосовали за великого и ужасного Рубика. И подпишись, заебал."},{"id":"uchus-igrat-07","f":"igrat","r":"r","title":"Лич","t":"Учусь играть в Доту! Лич, я не знаю, либо мне так везло, либо герой сейчас мегасильный, либо против меня играли агенты Габена. В каждом матче у меня было более 25 ассистов и более 10 килов. Я сам охуевал от матча к матчу. Герой обладает вообще всем, чем только можно: замедление, контроль, щит. И самое приятное, невъебенная ульта, которая вместе с шардом может снести всю вражескую тиму, а ещё реген маны за счёт поедания своих крипов. Каждую игру мой нетворк был на уровне тройки или мидера, хотя по факту я ничего особенно не делал, как обычно, стакал, отводил и так далее. Герой супер-крутой, наверное, один из самых лёгких и понятных из всех, на ком я играл. Это невероятный герой, с которым можно просто зайти в игру и уже вносить импакт команде. Он заслуживает золотую медаль Габена. А почему именно золото? Подробно написал в ТД. А дальше у нас престарелый дед с лошадками. И подпишись. Заебал."},{"id":"uchus-igrat-08","f":"igrat","r":"r","title":"Открыл рейтинг","t":"Учусь играть в доту! Я открыл рейтинг. Почти два месяца мне на это потребовалось, а точнее, 165 матчей и всего 230 часов в доте. Конечно, из них много матчей с ботами, куча времени в пробе героев и так далее. Открыв рейтинг, сразу появляется несколько вопросов: что такое калибровка? Почему я не могу играть на той роли, которой хочу? И причём тут вообще жетоны, как их выбивать и использовать? Как мне объяснили, чтобы получить жетон. Надо выбрать все роли. И если мне выпадет, допустим, роль Керри или Мидера, на котором я не умею вообще играть, я же просто заруиню всю игру команде. А также есть ли награды за рейтинг, условно сезоны с призами? Или тут рейтинг просто показатель твоего скилла, которым ты можешь гордиться? А у тебя какой рейтинг? И подпишись. Заебал."},{"id":"uchus-igrat-09","f":"igrat","r":"r","title":"Никс","t":"Учусь играть в Доту! Никс. На жуке можно очень быстро передвигаться по карте, что позволяет загангить какую-то линию либо пропушить её. Он способен молниеносно забирать одиночные цели, инвиз, тан, догон и второй скилл. Но проблемы начинаются, если противников вдвое и больше. Мне либо убегать ...Что не всегда удаётся, либо драться руками, но чаще это заканчивается смертью. Достаточно тяжело стоять на линии против оранжевиков, поэтому я аккуратно старался из кустов давать стан, чтобы мне сраку не подпалили. Кстати, это первый герой, на котором я не покупал аганим. Он даёт способность, где ты можешь закопаться под землю, оставив только одну жопу. И это не БДСМ, наклонности жука. Хотя способность-то хорошая. Но как будто за эти деньги есть предметы, которые дадут больше импакта. Герой заслуживает золотого Габена. А дальше у нас сопля в виде шара, на котором я вообще не знаю, как играть. И подпишись. Заебал."},{"id":"uchus-igrat-10","f":"igrat","r":"r","title":"Шейкер","t":"Учусь играть в Доту! Шейкер, когда я играл на этом герое, мне казалось, что враги фокусят меня постоянно. Где бы я ни был, в меня всегда влетают два-три героя. До блинка и после — это вообще как будто два разных персонажа. Пока ты на своих копытах добежишь, тебя уже разнесут. Совсем другое дело, когда ты просто появляешься из ниоткуда, и на голову падает мохнатая жопа. Ах, мечты, которая за пару ударов отправляет всех в таверну. Скиллы у него все приятные, но первый мне зашёл больше всего. Спасти своего кора? Да без проблем. Стопнуть убегающего противника вообще легко, перекрыть путь. Тоже, пожалуйста. У Агани есть приятное улучшение: можно сидеть в засаде, как ниндзя, выпрыгивать и раздавать автографы всем подряд. Единственное, надо научиться стоять против дальников, потому что это прямо очень больно. В итоге я вручаю ему золотого Габена. И подпишись. Заебал."},{"id":"uchus-igrat-11","f":"igrat","r":"r","title":"Чен","t":"Учусь играть в Доту! Чем? Многие просили на нём поиграть, не понимаю почему. Ведь герой достаточно простой. Геймплей на чене чисто семейный. Собираешь всех местных наркоманов, клофелинщиц и потомственных алкашей и идёшь всем этим зоопарком бушевать на линии. Чисто батя на выгуле. Ага, попался! На деле меня унижали на линии даже свои же крипые. Мало того, что нужно героем управлять, так ещё этими мелкими пиздюками. Это потом я посмотрел гайд, что можно упростить управление, а не как я мышкой всё делал. Мышкой, Карл. Я пытался раскрыть героя, но по итогу вскрыли меня. Даже Инвокер мне казался лёгким по сравнению с ним. Чен улетает с бронзовым Габеном подальше от меня. Я ещё не готов к нему. А дальше у нас пока не знаю. Голосуй в Телеграме и подпишись. Заебал."},{"id":"uchus-igrat-12","f":"igrat","r":"r","title":"Леон","t":"Учусь играть в Доту! Лион — один из самых популярных героев. Я уверен, что его создали для настоящих мужчин, и на это у меня три причины. Во-первых, он бьёт по земле огромной шипастой ёлдой. Во-вторых, мастерски сосёт, как у своих. Таки у чужих, универсальный солдат такой. Ну и, конечно же, то, что делает его таким могучим — пальчик-ванальчик. А если докупить секретный вар за 4 200, получится проход в туза без вазелина, там никто не устоит перед его мощью. Ебать! А, мама, мои трусы! И как вишенка на торте, если против вас иллюзионисты, с двадцать пятым талантом Лион срать на них хотел, каждый на карте будет жёстко наказан этим БДСМ-тираном. Мужчина в форме получает своего золотого Габена и идёт готовить свой пальчик к следующей игре. А ты подпишись. Заебал."},{"id":"uchus-igrat-13","f":"igrat","r":"r","title":"Энигма","t":"Учусь играть в Доту! Энигма — герой с мелкими глистами. На линии мне было стоять комфортно. За счёт стана и глистов мы прогоняли всех под башню. Пиздюками очень удобно блочить компы или делать отводы, при этом самому не подставляться. Но, наверное, главная фишка этого персонажа — конечно же, ульта. Если её в нужный момент нажать, а перед этим третий скилл и команда не проебётся, то всех положим. У меня случалось, что я дал ульту в четверых. А команда просто пробежала дальше. И я такой: «А чё мне делать?» Герой мне показался очень командным и интересным. Научиться бы ещё грамотно глистами управлять. Энигма получает золотого Габена. А дальше у нас голосование в ТГ. И подпишись. Заебал."},{"id":"uchus-igrat-14","f":"igrat","r":"r","title":"Апнул второго героя","t":"Учусь играть в доту! Я апнул второго героя. Почти все игры играл либо на Гриме, если четвёрка выпадала, либо на пятёрке дазли. Максимально старался тащить, ибо я был на калибровке. И если сравнивать со своей первой калибровкой, тут 14 игр, 10 победных. Интернешнл всё-таки даёт свой эффект, что хочется побеждать, улучшать свою игру. Начал на четвёрке почти каждую игру стакать тройку. В идеале доводить до пяти стаков на обоих кемпах. Пытался разбирать реплеи, как двигаются саппорты, как ставят ворды, но в паблике не всегда получалось повторить. Для кого-то может показаться, что ран-герой — это ничто. Но я вот что хочу сказать: пошёл на хуй тогда, мразь! Я полгода назад про Доту даже не знал, а ты тут пиздеть будешь. Смотря International, меня вдохновляет лучше играть. И есть один герой которого я даже начал тестировать. Но он вообще не саппорт. Это Эмбер Спирит. Когда-то я начну играть на меду и солью весь рейтинг нахуй. Подпишись. Заебал."},{"id":"uchus-igrat-15","f":"igrat","r":"g","title":"Джакиро","t":"Учусь играть в Доту! Джакира — герой, на котором ты можешь нажимать кнопки хоть жопой, и всё равно вносить какой-то импакт. А чтобы проиграть линию, тебе нужно буквально ослепнуть, и то не факт, что поможет. На линии я старался постоянно хорасить противника, чтобы у него даже намёка не было приблизиться к попке моего Керри, потому что она моя. Одна из самых приятных фишек Джакиры Он прекрасно ломает башни, поэтому если появляется возможность что-нибудь спушить, я сразу шёл туда и начинал плеваться во всё подряд. Но самое вкусное начинается, когда в команде есть долгий контроль. Кто-то держит противников на месте, ты просто вываливаешь оттуда все свои кнопки, и дальше начинается какое-то месиво из говна и мочи. Герой мне понравился, простой, понятный, кнопки, сделаны специально для таких, как я, умнейших людей планеты. Поэтому золотой Габен летит к нашему двуголовому дракону. А ты голосуй в ТГ за следующего героя и подпишись. Заебал."},{"id":"uchus-igrat-phoenix","f":"igrat","r":"g","title":"Феникс","t":"Феникс — герой, у которого одно яйцо. И переживает он за него больше, чем я за свой рейтинг. Вообще герой оказался намного сложнее, чем я думал. Не туда полетел — жопу порвали. Не так нажал лазер — жопу порвали. Зашёл в игру — жопу порвали. А скиллы поначалу ещё и с большим КД, поэтому использовать их нужно с умом. При этом почти все способности ещё и жрут твоё ХП. Поэтому нужно балансировать между тем, чтобы внести побольше урона и чтобы тебе самому жопу не порвали. Ну и, конечно, яичко. Правильно поставить яйцо — это уже отдельное искусство. Нужно понимать, кто сможет его разбить, сколько у врагов ударов и в какой момент его вообще можно позволить себе нажать. Причём перед яйцом желательно выжать из героя вообще всё: прожать скиллы, влететь куда надо и напоследок ещё лазером из жопы пострелять. А ещё Фениксом можно делать тройные и даже четверные стаки. Но для этого надо так надрочиться с таймерами, что проще получить второе яйцо. Станов у героя нет. Зато урона он может выдать столько, что глаза у противника выжжет раньше, чем тот поймёт, что вообще произошло. Однояйцевый мне очень понравился. Но это точно не герой, которого ты понимаешь за две игры — тут реально нужно учиться правильно летать, жечь и беречь самое дорогое. Золотой Габен определённо летит к нему. А ты подпишись уже, заебал."},{"id":"uchus-igrat-oracle","f":"igrat","r":"g","title":"Оракл","t":"Оракл — один из легчайших саппортов, чтобы заруинить игру. Просто кидаешь скиллы рандомно — и кто-нибудь обязательно умрёт. Иногда даже враг. А если серьёзно, герой требует понимать, что и когда нажимать. Скиллы простые, но ими можно как спасти союзника, так и самому его добить. Ну или случайно похилить врага. Комбинаций немного: хочешь дамажить — третий и первый. Хочешь хилить — второй и третий. Звучит просто, пока не начинается файт и мой мозг не выключается. С ультой главное не заруинить момент, а потом третьим как ненормальный пытаться человека выхилить. Ещё Оракл умеет предсказывать руны. Только всем как будто вообще похуй. Аганим я ни разу не покупал: я бедный саппорт, и ещё с этими картами заёбываться не хочу. Короче, герой требует быстро понять, что именно сейчас нужно нажать. Как вы понимаете, мой тупой мозг этого не умеет. Серебряный Габен достаётся Ораклу. Голосуй за следующего героя. А ты подпишись уже, заебал."},{"id":"standalone-01","f":"solo","r":"r","title":"Я думал, что будет легче — сложность Dota для новичка","t":"Я думал, что будет легче. Ведь обычные игры дружелюбны к новичкам, тебя ведут за руку, дают время привыкнуть, но Dota. Дота просто сожжёт тебя и тут же вызрет обратно. В игре 127 героев со своими способностями, пассивками и всякими фишками, которые ты должен хоть немного знать. А если это ещё не сломало твой мозг, то привет в магазин с предметами. Там тоже всё непросто: сотни предметов, каждый с эффектами, активками, пассивками, хуевками, которые надо успеть использовать в нужный момент и знать, как они работают. А пока ты пытаешься понять, что купить, тебя уже хуесосят в чате. Если что-то купил, тебя хуесосят за то, что купил именно это. А если не купил, тебя хуесосят за то, что не купил."},{"id":"standalone-02","f":"solo","r":"r","title":"All Pick или Turbo — что лучше новичку","t":"Олпик или Турбо? Какой же режим лучше начинать играть новичку? Именно этот вопрос я задал сам себе. С одной стороны, с Турбо можно по-быстрому опробовать разных героев и присмотреться к игре. Матчи проходят быстро и не напряжённо. Но Турбо, ты как будто бы не чувствуешь экономику и даже не стараешься следить за ресурсами. Тебе не нужно пытаться добивать крипов. Ведь деньги появляются как будто сами по себе. Опять же, возможно, я неправ. Давайте лучше спросим у чата. Лучше удалить доту. А вы как думаете, что же выбрать новичку?"},{"id":"standalone-03","f":"solo","r":"r","title":"Может, удалить Доту?","t":"Может, удалить Доту? Руки тянулись. Руки грешные, убери от доты! Но потом я подумал: если я не могу быть героем, я стану проблемой. Да, меня всё ещё периодически, как бы это мягко сказать, обоссывают."},{"id":"standalone-04","f":"solo","r":"r","title":"Как люди получают 300-й уровень?","t":"Как люди получают трёхсотый уровень? Это нужно играть 24 на 7? Я отыграл буквально месяц и всего лишь на двадцатом уровне. Да, я много, возможно, проигрывал, поэтому, в целом я новичок, лох, говно, ссанина. Давайте посмотрим, что же мне выпадет. Это же аркана будет. Нахуя. Так как я ничего не понимаю, я выбираю по такому простому приоритету. Что больше стоит, то и беру. В данной ситуации вот эти два грифона прекрасных, великолепны. Это что такое, блядь? А ты бы что выбрал в моей ситуации? И подпишись. Заебал."},{"id":"standalone-05","f":"solo","r":"r","title":"Инвокер как «простой герой для новичка»","t":"В доте существует огромное количество героев, от самых сложных, на которых нужно сотни часов, чтобы хотя бы понять, какие кнопки нажимать. Ну, например, Снайпер, Вайпер. Это реально тяжёлые персонажи. А есть другая категория, максимально простые, буквально для новичков, такие как Инвокер, Чен, Тинкер. Сегодня мы проверим, насколько Инвокер подходит для новичка и почему он считается одним из самых простых героев в игре. И что вообще может пойти не так."},{"id":"standalone-06","f":"solo","r":"r","title":"История про жестокое комьюнити Dota","t":"Я не думал, что комьюнити Dota реально может быть настолько жестоким. Я всё могу стерпеть: ломание шмоток, руинеров, грязь в чат, крики Voice, да даже игра с женщиной. Но то, что произошло вчера, уже переходит все границы. Я правда пытался делать вид, что ничего страшного не случилось. Но когда человек обещает на весь мой Telegram-канал и мы с подписчиками сидим и ждём, как голодные львы нотались твою фотку с качественным, да хоть каким-то пенисом. Это было подло. Я думаю, ваше сердце, как и моё, сейчас, разбито. Но что же нас ждёт дальше? Куда подевалась крепкая мужская дружба? Мы что, теперь будем заходить друг другу в тыл только ради того, чтобы сломать трон? Вы ещё скажите, что вы смотрите порно с женщинами. Мне стыдно за вас. Ах да, подпишись, заебал!"},{"id":"standalone-07","f":"solo","r":"r","title":"«Тёмный карнавал» — первый ивент","t":"«Тёмный карнавал» — мой первый ивент в Доте. Встав ночью чисто посрать, моя личка и в целом соцсети все были завалены, что вышел новый ивент. Многие пишут, что ивен — говно, скины — говно, Габен — говно. Сразу скажу, мне ивент понравился, но мне не с чем сравнивать. Ну, только если взять высшее изобретения Габена, Квартера. Я собираюсь забрать с ивента максимум, открою всю коллекторку, выкуплю все личности, комнаты и так далее. Обидно, конечно, что нельзя никак получить топовые арканы, типа дровки, квопы и так далее. Но и на этом спасибо. Стоит ли снимать мне видосы? Как я открываю всё это говно. Или нахуй это кому надо? Все хотят только одного — обосрать Габена. Пиши, как тебе ивент, и подпишись. Заебал."},{"id":"standalone-08","f":"solo","r":"r","title":"Гобен, какого хуя? — покупки и сокровищница","t":"Габен, какого хуя? Обычно, когда покупаешь сразу всё в одном наборе, то делает небольшую скидку. Но этот парень так на яхту не заработает, всё до центу у тебя заберёт. В итоге пять личных и потайные комнаты вышли 89,94. Даже ни одного центика не уступил нам. То же самое, что по отдельности покуп. Дальше я пошёл крутить сокровищницу. И тут Габен, наверное, увидел, что я и так занёс на еду его мамаши достаточно и подогнал мне голову на тринадцатой крутке. Я только зря покупал 33 сокровищницы. Но зато выпало много повторок, включая ещё одну голову. Позже раздам своим подписчикам в Телеге, может, хотя бы им пригодятся. Дальше я планирую покрутить лавку конфет, но зная свою удачу, мне ничего не выпадет. Пиши, что тебе выпало, и подпишись. Заебал."},{"id":"standalone-09","f":"solo","r":"r","title":"Я ограбил Гобена — результаты ивента","t":"Я ограбил Габена. За время ивента я прокрутил около 120 круток и получил больше, чем ожидал. Несколько аркан, а именно на пуджа, фантомку и Сефа. Много курьеров и бордов я забирал просто для коллекции. Выбил два чайника, и с них упал, как мне сказали, легендарный меч на Свэна, хотя его Emortalка мне больше понравилась. И на Элдер Титана, его ёлда. Новичкам везёт, и я полностью доволен лавкой. Ведь многие мне писали, что они прокрутили более 100 круток, а им ничего толкового не выпало. Возможно, позже ещё на прокруток 50 задоначу. Пушка на дазла мне не помешала бы. Переходи в ТГ, там розыгрыш автоматонов, арканов, но главный приз — личный осмотр твоей анальной трещины. И самое главное — подпишись. Заебал."},{"id":"standalone-10","f":"solo","r":"r","title":"Новая система рейтинга — путь до рыцаря","t":"После того, как Габен подарил им новую систему рейтинга, где за победу дают 40, а поражение снимают около 25 ПТС, то до рыцаря поднимается кто угодно. Даже если ты однорукий инвалид с двумя культями, ну, примерно как я, то тебе понадобится около 120 игр. Но если подняться с рекрутов так легко, то что за монстры вообще там остались?"},{"id":"standalone-11","f":"solo","r":"r","title":"В рейтинг стало легче играть после старта ивента?","t":"В рейтинг стало легче играть или мне просто кажется, но после старта ивента как будто все ринулись дрочить на билеты в турбо. Каждая катка — это двадцатиминутная ебля в жопу. Но потом я прошу отчима остановиться, ведь я тоже хочу фармить билеты. В итоге как будто все потные игроки просто ушли с рейтинга в Турбо. Я даже попался против команды, которая с нулевой минуты не хотела играть и просто слила нам катку. Я понимаю. Кто-то из вас скажет, что я просто стал лучше играть, начал более осмысленное передвижение по карте и так далее. Но, блядь, это коммьюнити-доты, кляп в рот, кувалду в жопу. Ну хоть кто-то бы это сделал. И всё же потом и кровью я апнул страж-1. Да, это, конечно, не Титан, но мелкими верными шагами мы и до Титана дойдём. А ты не замечал, что в рейтинг стало играть легче? И подпишись. Заебал."}];
export const AI_TELEGRAM_EXAMPLES: readonly { k: string; t: string; g?: 1 }[] = [{"k":"caption","t":"Реально ли начать играть в Доту в 2026 году?\n\n<ссылка>"},{"k":"caption","t":"Знаю, прошло 200 лет, но вот...\n<ссылка>"},{"k":"post","t":"Вы когда-нибудь видели Пуджа, который боится собственного хука больше, чем врагов? Знакомьтесь, это я. Первый раз на Pudge в роли «Мясного саппорта». Пытаюсь понять, почему враги постоянно отходят в сторону, когда я нажимаю Q.\n\nЯ чаще по крипам попадал крюком, чем по героям....\n\n<ссылка>"},{"k":"post","t":"Пора заводиться сигнатуркой, с вашей помощи я отобрал героев, которых стоит попробовать. Если я кого-то упустил и нужно кого-то добавить, вы обязательно пишите.\n\nПланирую на каждом играть по 2-3 игры, чтобы немного понять нравиться ли герой."},{"k":"post","t":"Посмотрел несколько гайдов, как будто аппарата берут только на 5-ую позицию, попробую наверно на ней сыграть.\n\nВопрос знающим❓\nКакой взять аспект, в гайдах разные аспекты советуют, хотя можно попробовать одну катку с одним, другую с другим"},{"k":"caption","t":"Оказывается у меня закрыты комменты, вот я уебан конечно, вроде открыл их…"},{"k":"post","t":"Я только сегодня узнал о квит кастах. Почему дота ни как не показывает о таком функционале?\n\nПока прицелишься , потом подтверждать надо действие и только потом скилл срабатывает, за это время, противники успевали сходить в магазин, погулять с собакой, а потом вернуться и взорвать мне жопу с прокаста.\n\nПока настроил только для 1 героя, или стоит сразу для всех настроить? Предметы тоже надо будет настроить, руки еще не добрались."},{"k":"post","t":"Моя первая игра на аппарате и на 5 позиции. Все тайминги проебал, пытался стакать и в целом помогать команде, герой сильный, но и пизды получает знатно.\n\nПопробуем еще пару каток отыграем на нём и посмотрим, что получится"},{"k":"caption","t":"Вот это руководство использую, самому пока мозгов у меня не хватает все это составлять"},{"k":"caption","t":"Вторая игра, тут пиздячек прям много прилетало, толик квадроцикел разьебал всех"},{"k":"caption","t":"Приятно конечно добивать так"},{"k":"caption","t":"Решил покрутить, упали две акулы, что делать со второй хз, продать нельзя, лучше бы tiny упал, но Габэн зажал((\n\nВ целом это лудка какая-то..."},{"k":"caption","t":"Моя 3 игра на аппарате. Позже напишу мнение о герое и поставлю его в рейтинг и перейдём к другому персонажу\n\nпытались сражать но мы проиграли..."},{"k":"review","t":"Аппарат\n\nПрекрасный герой с пиздец какой дальностью атаки. Просто стоишь за союзниками и на чили раскидываешь кнопки. Я отыграл 3 игры на нём. Одна игра на пятой позиции, а две на четвёртой.\n\nТы стреляешь из стратосферы, стоишь за спинами союзником и нажимаешь кнопки. Ультра что-то с чем-то, можно в другой части карты наводить суету, при этом находиться на фонтане и наслаждаться жизнью.\n\nНесмотря, что мне герой понравился, мне кажется он не сильно подходит для 4 позиции. Проблема с контролем: Чтобы сработал твой единственный стан (Cold Feet), враг должен простоять в зоне 4 секунды. Если ты приходишь гангать мид, а у врага есть хоть какой-то эскейп или просто быстрые ноги, то он просто убежит и план капкан провален.\n\nВ моём рейтинге аппарат получает золотого Габена!","g":1},{"k":"post","t":"Решил остатки скинов обменять на 1 крутку в итоге залетел мужик в мой инвентарь.\n\nРаз выпал скин, то следующего героя возьму Tiny. Сейчас посмотрю гайды, чтобы хотя бы понимать как на нём играть и тд. И пойду фидит катку)"},{"k":"caption","t":"как пройдёт 30 дней подарю желающем, ибо хз что с ними делать, также еще куча других скинов из скоровищницы"},{"k":"post","t":"Оххх... Моя первая игра на тини\n\nС самого начала игра не задалась, Вайпер со снайпером не поделили мид поэтому просто стояли на нём, я один стоял против axe и аппарата они меня гнобили как котёнка(((\n\nВ целом персонаж неоднозначный, нужно привыкнуть к броскам, иногда не того бросал и не туда(("},{"k":"caption","t":"Втора игра на Tiny.\n\nБыло потно немного, часто вообще не того кидал, но старался жить и быть полезным"},{"k":"caption","t":"такая шляпа выпала..\n\nГабен, где аркана?"},{"k":"caption","t":"Моя статистика по всем играм, которые я сыграл не с ботами."},{"k":"caption","t":"Габэн где обнова?"},{"k":"post","t":"Вместо того, чтобы играть в доту и заносить щекели Габену в карман, мне приходиться носиться по городу и выбирать подарки.\n\nНадо придумывать мужской праздник, того же масштаба как 8 марта, ибо 23 февраля это чисто 2 носка и мои же старые труханы идут в подарок…"},{"k":"post","t":"Что делать, когда просто никто на мид не пошёл, одну линию чуваки стояли в 3. Наш керри просто бегал по карте с одной позиции на другую.\n\nЧто касается меня, старался меньше не умерать при этом всячески мешать, но я хз как тут можно мне было переиграть их.\n\nПросто прыгает хускар и все, кабина в таверну летит...."},{"k":"caption","t":"С 8 марта джентльмены."},{"k":"caption","t":"Мужчины, может розыгрыш какой-то замутим? 2 премиум тг на 3м или 1 аркану? Ток я хз как в доте что то дарить? Или нахуй эту идею?"},{"k":"caption","t":"Многие пишут, что хотят со мной поиграть. Если вы этого не боитесь, то держите код дружбы, приму всех.\n\n337578062"},{"k":"post","t":"Разыгрываем две дота плюс на 6 месяцев. Будет два победителя. Для участие чисто быть подписанным и там бот выберет уже сам. Я либо на деньгами вам дам , либо через сервисы вам закину по логину"},{"k":"caption","t":"Мне много кто написал поиграть в доту, можем собрать пати и пойти"},{"k":"post","t":"Всем привет, заебала это работа конечно... не даёт в доту играть\n\nДля ролика сегодня играл последнею катку на Tiny, завтра уже опишу своё мнение по поводу этого героя и конечно присужу его медаль Габена.\n\nМногие пишут, чтобы поиграл с вами, к сожалению я не могу каждый день играть, а если и играю то только в свободное время.\n\nВозможно вечерком будет часик времени, но не обещаю."},{"k":"call","t":"Могу с вами сыграть 1 игру, 1 человек уже есть у нас в пати"},{"k":"call","t":"Могу сыграть еще 1 игру, но уже давай те с другими людьми,чтобы все могли поиграть"},{"k":"post","t":"Нихуясебе... Нас уже 100 человек! 🤯\n\nКто бы мог подумать, что на ноунейма, который только учится нажимать кнопки, подпишется сотня человек...\n\nПогнали фидить дальше, теперь уже в промышленных масштабах!","g":1},{"k":"review","t":"Tiny\n\nВ моем личном рейтинге этот каменный гигант уверенно забирает свою заслуженную награду - медаль серебреного Габена. Персонаж с огромным каменным сердцем. И еще более каменным членом, который он клал на всех вражеских героев, пока те пытаются его пробить.\n\nМне понравился:\n• Двойной контроль: У него, по сути, два стана. Врываешься, даешь прокаст — и вражеский саппорт превращается в аккуратную горку щебня.\n• Каменная валына: В любой момент можно вытащить дерево и начать раздавать по кабинам с руки.\n• Живучесть: Капец какой плотный герой. Настоящий кусок скалы, об который враги ломают зубы весь ранний геймплей.\n\nНо есть один нюанс — Toss: Использовать его правильно — это отдельный вид искусства. В воздух у меня летит вообще всё: крипы, иллюзии, мои же тиммейты прямо в центр вражеской пачки... всё, кроме нужного героя. Пытаешься пафосно выкинуть врага под свою вышку, а туда летит... очередной бесполезный крип. Враг ржёт и уходит на лоу-хп, а ты чувствуешь себя максимально неловко.\n\nГерой хороший, если рядом нет лишних юнитов и у тебя железные нервы при нажатии второго скилла.\n\nСледующим на очереди будет Огр Маг — посмотрим, на что способен этот двухголовый гений и сколько раз у меня вылетит мультикаст.","g":1},{"k":"caption","t":"Матч интересный, как будто были все шансы победить, но нас разьебал мееро подчистую."},{"k":"call","t":"Кто хочет сыграть в доту, желательно с кем я еще не играл?"},{"k":"post","t":"Прежде чем идти со мной играть, подумайте пожалуйста, выиграли только благодаря этим 3 легендам.\n\n1 у нас афк, и я фидер, который умерает каждый раз, как враг пёрнет.\n\nПростите парни, играл как мог, но не смог....","g":1},{"k":"caption","t":"Как вам обнова?"},{"k":"caption","t":"Сижу на правах, засыпаю…\n\nА мог бы на 4 фидить вам игру."},{"k":"caption","t":"Скоро…\n\nНа ютубе…"},{"k":"caption","t":"Крч, вот\nСмотрите или не смотрите. Но лучше смотрите\n\n<ссылка>"},{"k":"call","t":"Кто в доту пойдёт? наконец-то минутка выбилась свободная"},{"k":"post","t":"Поясню, почему именно 4 героя на выбор я дал. Я всё равно планирую поиграть на всех, но если выкинуть полный список персонажей, на которых я ещё не играл, там получится такая «куча мала», что мы вообще ни к чему не придём. Каждый будет топить за своего, и в комментариях начнется хаос.\n\nПоэтому я буду постепенно выкидывать список из четырёх героев, чтобы мы могли нормально выбрать и сфокусироваться на конкретных целях, вместо того чтобы распыляться на всё сразу."},{"k":"caption","t":"А у кого какие ммр тут? Есть прям жёсткие? показать пару фишек каких-то может можете?"},{"k":"post","t":"Вы по разным причинам не можете общаться voice, либо порядочность маленькая либо пенис, не важно.\n\nНо когда вы пишете мне в личку во время игры, я отвлекаюсь. Я и так играю как говно, а тут еще приходится переключаться на сообщения и передавать инфу другим — получается полная херня.\n\nЯ создал дискорд-сервер, чтобы мы могли собираться в войсе или вы сами могли там искать пати. Сервер пока сырой, времени на расширение нет, но для дела хватит.\n\n<ссылка>"},{"k":"review","t":"Ogre Magi — когда две головы работают лучше, чем моя одна.\n\nЭтот двухголовый интеллект превращает любую катку в сеанс игры в казино: либо ты бог удачи, который станет врагов по кд, либо очень толстое существо, которое просто смешно бегает по карте. Угадай кто я )))\n\nКогда залетает X4 в лицо врагу — это лучший звук в игре. Легальный чит, который не контрится ничем, кроме воли великого рандома. Когда проходит мульти-каст, враг просто испаряется, а ты чувствуешь себя самым удачливым человеком на сервере. Кинул бафф на керри, кинул игнайт — и пошел пить чай, пока команда делает фраги за тебя.\n\nНо есть один нюанс — Везение:\nПытаешься красиво шотнуть врага станом, ждешь искры, бури, безумия... а вылетает одна слабая тычка. Враг просто ловит фейспалм и спокойно уходит, а ты стоишь и слушаешь тишину вместо «динь-динь-динь». Ты можешь быть гением позиционки, но если не прокнуло — ты просто зритель.\n\nOgre Magi получает заслуженное Золотого Габена!\n\nСледующим на очереди будет Techies."},{"k":"caption","t":"Начнём играть на Techies, пишите кого следующего брать, и на основе четверых популярных героев сделаю опрос.\n\np.s. желательно саппорты..."},{"k":"caption","t":"Немного готовлюсь..."},{"k":"caption","t":"Опять хускар нас отрахал.\n\nВ целом теперь немного получше на течисе получаться стала, поставил бомбочки на колесо мыши и норм."},{"k":"caption","t":"Работают профессионалы ..."},{"k":"call","t":"Кто хочет поиграть? В приоритете кто со мной не играл"},{"k":"caption","t":"Кто ещё не играл со мной, но хочет? 4 места свободный"},{"k":"caption","t":"Обычно я присылаю как за щеку глотаю, сейчас сделаю исключение\n\nСпасибо команде"},{"k":"review","t":"Techies\n\nПервая игра была полный пиздец. Я отыграл со счетом 0-20, мне столько хуёв накидывали, что даже отчим в ахуе. Но с каждой каткой становилось всё лучше и лучше, а совет поставить бомбы на колесо мыши вообще открыл глаза — теперь кнопки прожимаются получше, а не как у инвалида.\n\nКогда ты влетаешь в замес, расставляешь мины и враги просто разлетаются в куски — это чистый кайф. Ты разрываешь ебало оппоненту, и он даже не успевает ничего сделать. Но если хоть чуть промахнулся прыжком — ты превращаешься в самый легкий фраг на карте. Скорость атаки у него просто смешная, машет руками как в киселе, поэтому если не убил с прокаста — остается только бежать со всех ног, пока не догнали и не унизили.\n\nЭто герой-качели: либо ты держишь в страхе всю карту, либо просто бегаешь как обосранный и молишься, чтобы не сдохнуть в очередной раз.\n\nВ моем личном рейтинге этот ебанутый пиротехник забирает свою заслуженную награду — золотого Габена.\n\np.s. a вот про следующего героя, будет отдельный пост. Я должен подготовиться, что бы не обосраться ещё на этапе загрузки матча","g":1},{"k":"caption","t":"Что выбрать?\n\nскидывайте что вам выпало"},{"k":"review","t":"Инвокер...\n\nВ принципе, тут можно было бы ничего не писать — и так всё понятно. Герой, который не прощает халтуры, так что пришло время серьезно потеть. И я сейчас даже не про пальцы, а про мозг. Хотя, будем честны — судя по моей игре, он у меня где-то в отпуске, так что придется договариваться с тем, что осталось.\n\nЕсли на Тини я просто не попадал тоссом, то здесь мои пальцы превращаются в перепутанный клубок. Способностей столько, что пока я вспоминаю, в каком порядке всё нажимать, враг начинает думать, что я просто АФК или завис.\n\nЧтобы в катках не стоять как декорация, решил действовать системно\n- Тренировка: Задрачиваю комбинации до тех пор, пока руки не начнут делать это на автомате.\n- Боты: Буду становиться королём ботов.\n- Реальные катки: Иду фидить в All Pick.\n\nЕсли увидите в игре Инвокера, который стоит столбом — не бейте, это я. Я просто пытаюсь вспомнить, где у него кнопка «победить»."},{"k":"caption","t":"У кого желание сыграть 1 игру есть?"},{"k":"caption","t":"Выпал такой сундук? Что делать с ним? Стоит ли ключ купить либо там говно какое-то упадет"},{"k":"post","t":"Моя первая игра на этом мужчине. В быстрых замесах всё путается, и либо не то что надо вылетает, либо меня убивают.\n\nИграл аккуратно, в целом я старался стопать врагов, кидал тарнадо, сосал ману , да и просто сосал.\n\nДальше больше..."},{"k":"call","t":"кто хочет в turbo поиграть?"},{"k":"post","t":"Это пизда. p.s. инвокер в бане был\n\nПопробовал на белке, я хз что делать, когда вся моя команда решила просто на 1 лайн пойти и получала пизды от пуджа, в это время меня тарабанил скаймак с фантомкой...."},{"k":"caption","t":"Кто в turbo хочет пойти? Присоединяйтесь к группе"},{"k":"caption","t":"Вторая игра на вокере.\n\nМогли победить, но проиграли. Как всегда..."},{"k":"caption","t":"Как всегда говно..."},{"k":"post","t":"Кому вообще верить в этой доте?\n\nСерьёзно. Я как новичок просто пытаюсь понять, что тут вообще правильно делать.\n\nВот элементарный пример — Огр. Беру один аспект — мне пишут, что это говно, бери другой. Беру другой — говорят, что этот ещё хуже и «так вообще никто не играет».\n\nИ ладно бы был один «правильный» вариант. Но нет. Один уверяет, что правый аспект — единственный нормальный, второй доказывает, что только левый работает, и всё — начинается классическая дота: спор, аргументы, и в какой-то момент уже не про игру, а про то, у кого ммр больше и «кто вообще имеет право говорить».\n\nИ ты просто сидишь и смотришь на это как на шоу.\n\nДальше — Инвокер. Там вообще отдельная история. Берёшь какой-то предмет — сразу вопрос: «почему это купил?». Один говорит, что это база, второй — что это мусор и нужно было брать вообще другое.\n\nИ опять то же самое — люди между собой не могут договориться, что правильно.\n\nВ итоге ты вроде как хочешь научиться, начинаешь искать информацию, открываешь про-трекер, смотришь, какие билды берут про-игроки, какие аспекты выбирают, иногда заходишь на ютуб, чтобы хоть как-то структурировать это всё.\n\nДелаешь «как надо»…\nа потом всё равно оказывается, что «не так».\n\nИ вот в какой-то момент появляется ощущение, что в доте нет одного правильного ответа.\n\nЕсть просто куча мнений.\nИ каждое — «единственно верное».\n\nИ ты либо выбираешь что-то одно и играешь, либо пытаешься угодить всем и просто сходишь с ума.","g":1},{"k":"caption","t":"Думаю ещё 1 игру поиграю на инвокере и будет делать на нём како-то вывод и переходит к следующему герою."},{"k":"caption","t":"Пока я доигрываю катки на Инвокере, вы накидайте героев ещё, только теперь попроще плз, без ваших ченов хуенов\n\np.s герои для 4-5 позиции"},{"k":"call","t":"Кто в доту?"},{"k":"caption","t":"опять говно... все стабильно"},{"k":"caption","t":"Ну что будем в доту играть?"},{"k":"caption","t":"почти проиграли, угадайте кто всех спас?\n\nне я"},{"k":"call","t":"Кто 5 на 5 в лобби хочет? не хватает 2 человек"},{"k":"caption","t":"я хз как это работает, сет вместе стоит 60 баксов, по отдельности собрал за 3 бакса примерно"},{"k":"caption","t":"Я если честно удивился, что я тут лучший игрок. Ибо много умирал..."},{"k":"call","t":"Кто в all pick пойдёт?"},{"k":"post","t":"Завтра уже более подробно опишу мнение про шаманчика, а пока вот вам фрагмент какие мувы могу я исполнять на нём. Я сам себя запер внутри змеек. Пробывал через А атакавать, но не получилось. Про то, что я могу с дагером перепрыгнуть я не додумался"},{"k":"caption","t":"Как вам обнова? Прощай аспекты….\n\nВсе изменения - <ссылка>\n\np.s. ну хоть споров не будет, какой лучше аспект"},{"k":"review","t":"Повелитель куриц.\n\nЯ бегал только с аспектом на курицу, мне показалось что 3 контроля у героя это очень сильно. Так же в пользу аспекта - прикольно, что можно противника запереть внутри змеек, правда один раз я запер там себя. Нормально так законтрил.\n\np.s. аспекты удалили - плак - плак\n\nС самого старта шаман очень сильно бьет, и если со мной активный напарник то мы быстро забираем одиночную цель. Но бывали игры когда я связываю, а керри просто бьёт крипа. Возможно за них он больше золота получит чем за кил. По ощущениям герой должен бегать только с командой, условно если на течисе я мог быстро шотнуть цель, то тут не получиться так сделать, да я могу кинуть ульту в него и завязать, но мне всё равно урона не хватает, возможно я что-то не так делал.\n\nЯ отыграл на нём больше 6 игр на 4-5 позиции. Герой оказался понятным и самое главное скилами я точно плохого что-то не натворю. Например, как на Тини крипов подкидывал, вместо героев. По скорости я не очень быстрый,но блинк помогал быстро перемещаться. Правда если меня ловят, то мои куриные бочка жарятся моментально.\n\nУльта у шамана прекрасно. С помощью неё я могу забирать тавера, рашана, часто пытался делать сплит пуши змейками. Но и во время драги нажимал её часто, и как всегда делал это неправильно. То кидаю змеек не вовремя, что все разбегаются просто, то змеек просто стирают за секунду.\n\nШаман мне очень понравился и это первый герой, которому я присуждаю алмазного Габена.\n\nдальше у нас идёт Zeus"},{"k":"caption","t":"Ну хоть жук нормальный, а остальное как всегда - говно"},{"k":"post","t":"Зевс в бан улетел, пришлось идти на шамана. У него появился приятный шард в виде дополнительной змеи, запераем врага в змее так ещё и большую мега змею кидаем и вяжем вот и чела нет."},{"k":"caption","t":"Мне авторские права вьебали, пришлось самому петь, строго не судите\n\nскоро..."},{"k":"caption","t":"Это что такое\n\n<ссылка>"},{"k":"caption","t":"Нафидил перефидил.\n\nТинкер нас почти в соло на свои турели насодил.\n\nЯ не знаю как работают лучшие герои, но меня чисто по приколу тут кинули"},{"k":"review","t":"Зевс — бог, который оказался сильнее меня.\n\nОтыграл на нем около 5 игр, и все они были, мягко говоря, дерьмовые. Дота пишет, что это один из легчайших героев, но мой личный тупизм с этим категорически не согласен. Как бы я ни старался, мне всё время тарабанят туза.\n\nУ деда есть прикольные фишки:\n\n- Палит варды: это реально экономит голду, на которую я могу купить себе немного покушать.\n- Прыжок, а если докупить шард, то их становится три, можно прыгать по писюнам, чем я активно и занимался.\n- Аганим даёт способность кинуть грозу в любую точку, можно помогать команде с таверны.\n- Ульта светит всех на карте, ну и как истинный саппорт, я всегда могу подтырить килл у своего кора.\n\nНо лично мне не хватило контроля. Да, на линии я сильный, второй способностью разваливаю лица на ура, но враги всё равно спокойно убегают, сверкая своими оголенными ляшками.\n\nЕсли дожить до слотов, то бить начинаю действительно больно. Но герой, которого считают легким, моим пальцам не поддался. Зевс прекрасен, просто я для него слишком туп. За это он получает серебренного Габена.\n\nА дальше у нас белка, не та которая у меня сейчас, а белка с орешками"},{"k":"post","t":"Саппорты всегда виноваты, первый раз я с этим столкнулся и немного моя срака сгорела конечно в этом матче. А теперь по порядку.\n\nВсе началось в самом начала, почему-то легеонка решила что ей стрёмно стоят на 3 и пошла на 5 позицию, но как офлэйнер. И мы с лионом в двоём остаивали нашу линию как могли, в целом все было неплохо.\n\nНо вот линия нашей героини упала первой и конечно виноваты саппорты, потому что вардлы им не поставили на ИХ линнию. Ну я как человек не гордый, как мог помогал им, ставил варды на перетяжку, гангал линию пока леона насаживали на все что можно.\n\nНемного перейдём на мид, там вайпер решил быть личной сучкой сфа, он то умирал от крипов, то сфа его уничтожал в нулину и вот у нас падает мид. Но виноваты снова саппорты. Ладно это мелочи, я начинаю сплит пушить и играть как зеркало, пока они снозят нам вышку, я им сношу на другой линии, но тут вопросы ко мне, зачем я им ломаю вышки, когда должен варды ставить.\n\nВ итоге легионка решила, что она стала жирной, как мать Габена и способно провернуть фишку с дуэлью и пошла сразу 1 против 5, ну и естественно отсасывала у всех по очереди, но опять виноваты саппорты, и пох что мы мёртвые, и пох что она 1 против 5.\n\nЯ даже думаю они нам с лионом кинула репорты, и конечно обидно, что были все шансы победить, но бывает и такое. Так что не расстраиваемся и продолжаем улучшать наши навыки, как фидить правильно. Вот у легионки немного поучился этому. Так что увидимся в играх","g":1},{"k":"caption","t":"А белка та кайфовая, еще научится всегда ультой попадать..."},{"k":"caption","t":"Неплохой клоквер, когда-то и до него очередь дойдёт, поэтому берем его"},{"k":"caption","t":"Так получается, что белка в бане, ну так кайфовая она. Пока шаманчика тренируем"},{"k":"caption","t":"немного обидно, что проиграли, но матч был хорош"},{"k":"caption","t":"Оказывается в телеге есть личные сообщение за бабки, пзд какой-то. Тип челы реально кому-то платят, чтоб написать сообщение"},{"k":"caption","t":"Делать деньги блядь вот так"},{"k":"caption","t":"Как будто ту каналы на выкачку бабла устроены, сообщение за бабки, реакции за баки, норм мутку мутятся"},{"k":"caption","t":"Хмм в тг даже бусты есть, как в дескорде, ебать я динозавр конечно…"},{"k":"review","t":"Я всегда знал, что у меня белка… но не думал, что когда-нибудь сяду за неё играть.\n\nГерой, который своими орешками может пробить любую жирную жопу, мне понравился. Сначала мне показался герой супер простой: да что там кинул орех, завязал, ультой стрельнул и убегаешь, пока жопу не порвали. Но на деле немного всё не так, кроме последнего пункта конечно.\n\nЯ орех и завязку кинул на квиккасты и сразу почувствовал, что комфортней играть, я могу быстро завязать противника и к счастью у меня почти всегда это получается. Да, бывает, что я быстрее кидаю саму привязку, чем орех, из-за чего получается просто пыль поднял.\n\nГангать линии на ней очень приятно включаешь смоук и просто ниоткуда появляешься и связываешь противника, прям как ниндзя какой-то. Но если запахло жареной белкой включаем 3 скилл и мчимся под деревьями подальше от этой заварушки, которую сам и начал.\n\nУльта — самый сильный и сложный скилл, ведь тут главное не промахнуться. Ну вы понимаете, что я пока на такое не способен, чтобы шотнуть сразу противника. Но сидя в кустах, ты целишься и вот летит моя стрела, смазанная белочьим говном, а противник отходит на сантиметр в сторону и можно начинать плакать. Депрессия на неделю гарантирована. С аганимом нормально так наёбывать игроков пока они думают, что ты просто по приколу стоишь и ультуешь, ты уже связываешь противника и в него 2 ульты летят. Но чаще, конечно, я это использовал, чтобы убежать.\n\nК сожалению, герой часто в бане сидит и хотелось больше на нём отыграть, ибо он супер кайфовый. Наша белка занимает золотого Габена под цвет своих орешков.\n\nНу а дальше у нас великий и ужасный Рубэн Рубэнович","g":1},{"k":"caption","t":"Кто готов пойти со мной фидить как про?"},{"k":"caption","t":"Ебать вас уже почти 215, что вы тут делаете? Я думал сюда подпишутся 3 человека, я ,мой отчим и мать габена.\nСпасибо, что остаётесь с таким нубом, как я."},{"k":"caption","t":"Весь тикток про 1 апреля, в доте вышло обновление, событие, патч, хуяч, лицо в сперме и это не шутка.\n\nВсех с 1 апреля."},{"k":"post","t":"Великий и ужасный Рубэн Рубэнови. Но тут я был не саппортом, меня просто кинули на мид и сказали любой ценой защищай его.\n\nГерой пиздец ахуенный, но нужно знать как минимум все скилы всех героев, чтобы воровать только лучшее..."},{"k":"caption","t":"Ребят у меня 2 уровень канала, могу повысить прайс на сообщение до 35к звёзд"},{"k":"caption","t":"Я ебанная деревенщина, как у меня канал стал 4 уровня, Габэн какого хуя"},{"k":"caption","t":"Быстро сгонял в турба на рандоме )) почти все афк встали, решил идти через супер билд"},{"k":"caption","t":"Бля кто шарит в авто, после зимы машина начала скрипеть, как мои колени"},{"k":"post","t":"Какая вялая команда попалась. Меня опять кинули на мид, ибо там никто не умеет играть на миду (тип я умею). В итоге ни 1 варда не было поставлено саппортами.\n\nКоманда как-то бегала по 1, по войсу все молчали, даже не пинговали, как будто с ботами играю.\n\nТут мне нравилось воровать палец лиона или пушки тинкера и пытался как-то дефать это дело. Но мидер из меня, как и саппорт. Смех да и только"},{"k":"caption","t":"Наконец-то рубика в саппорты взял. Но нас трахнула бруда, жёско, без смазки"},{"k":"call","t":"Кто в all pick готов ворваться ?"},{"k":"caption","t":"Поиграли немного, правда шторм всю игру фидил, но благодаря слаженным действия нашей команды, мы смогли выиграть эту битву"},{"k":"review","t":"Рубик!\n\nЯ отыграл около 4 игр на герое и 3 из них меня отправляли на миду стоять, ну вы понимаете какой из меня мидер. Все знают, что главная фишка рубика это воровать, но воровать тоже нужно уметь. Потому что я воровал всё, что в глаз попало, любую способность, начиная от хуй пойми что и заканчивая какими-то приятными ультами героев - типа члена леона или арена марса. Я так кайфово влетал, да умирал сразу, но как я влетал\n\nТелекинез очень часто выручал, герой убегает, а ты его сюда парниша, мы не договорили, или наоборот это ты убегаешь и кого-то как кусок говна откидываешь. Правда с шардом надо немного аккуратно, я бывало своих парней поднимал за жопу, но это уже скилл, вам далеко до такого.\n\nРубик может показаться простым, но нехуя. Нужно как минимум отлично знать все способности героев, чтобы своровать нужную способность, комбинировать ими, но мы пока воруем просто что попало и так понемногу изучаем способности, вот такой небольшой лайфхак, не повторять его. Более сложно становится, когда в мои руки попадает аганим и у теб появляется две украденные способности и все они говно конечно же.\n\nРубик несомненно получает алмазного габена и дополнительную награду - мамаша габена, а дальше с небольшим отрывом у нас побеждает Лич.","g":1},{"k":"call","t":"Кто готов в all pick пойти?"},{"k":"caption","t":"Первая игра на личе..."},{"k":"caption","t":"как всегда красота"},{"k":"caption","t":"Вторая игра на личе, но это игры с подписчиками, надо будет поиграть чисто самому, чтобы понять всю силу"},{"k":"caption","t":"Хоть мы проиграли, но игра была интересная. Я играл за собаку какую-то."},{"k":"post","t":"Моя третья игра на личе, но первая игра с рандомами. Последнии 5 игр, играю только на 5. Минусы рандома, что ноль комуникации, всех приходиться заставлять идти на обьекты или в драку"},{"k":"caption","t":"Моя 4 игра на личе и наверно самая тяжёлая"},{"k":"call","t":"Кто в турбо хочет?"},{"k":"review","t":"Лич\n\nЯ не знаю, либо мне так везло, либо герой сейчас мега сильный, либо против меня играли агенты габена, но на нём я просто разваливал кабины всем и каждому. Я отыграл 4 игры на нём, и 3 из них на 5 позиции. В каждом матче у меня было более 25 ассистов и более 10 киллов. Бывало и до 25 киллов доходило, я сам ахуевал от матча к матчу.\n\nГерой обладает вообще всем, чем только можно. Замедло есть, контроль в виде гипноза есть, щит есть, и самое приятное — невъебенная ульта, которая вместе с шардом может снести всю вражескую тиму. Геймплей максимально понятный. Главное — не подставляться, а то жопу порвут за секунды. Но это, в целом, правило почти для каждого саппорта. Почти халявная мана в виде поедания крипов даёт возможность вообще не париться за ресурсы и всегда быть готовым помочь своим тиммейтам.\n\nКаждая игра была настолько лёгкая и простая, что мой нетворс был на уровне тройки или мидера, хотя по факту я ничего особенного не делал. Просто стоял за командой и кидал щиты, контроль и замедло. Герой супер крутой, наверное, один из самых лёгких и понятных из всех, на ком я играл. Но на уровень алмазного я его поставить не могу, потому что, условно, тот же Рубик, на котором я играл хуже, мне зашёл больше. Мне самое важное не то, что герой в мете или не в мете, а насколько мне на нём нравиться играть, ведь смысл вообще играть в игру на герое, от которое не хочешь кайфовать даже когда проигрываешь.\n\nЛич это реально невероятный герой, с которым можно просто зайти в игру и уже вносить импакт команде. Он заслуживает золотую медаль габена.\n\nА дальше у нас дед с лошадками..."},{"k":"caption","t":"Я не ебу зачем вам эта инфа, но меня постоянно спрашивают это. Вот смотрите"},{"k":"caption","t":"Может кто знает, в последнее время дота стала лагать, габен какого хуя?"},{"k":"caption","t":"это была легендарная битва, мы лучшие их худших"},{"k":"caption","t":"Моя первая игра на котле с рандомами. Я даже не знаю, как тут можно было выиграть. Урса легенда"},{"k":"caption","t":"Я первый раз увидел хускара, который не смог. На личе каждую катку выигрывал, на котле отсасываю."},{"k":"caption","t":"вот это я понимаю насаппортил"},{"k":"caption","t":"норм закуп на мид"},{"k":"caption","t":"идет 15 минута"},{"k":"caption","t":"держался как мог,но не смог"},{"k":"call","t":"Кто пойдёт по фану поиграть?"},{"k":"review","t":"Котёл.\n\nПосле Лича, когда я мог одной рукой дрочить отчиму, а другой — его мужу, дед показался максимально заёбным. В каждой катке была какая-то дичь: либо я исполнял как уникум с 3 iq, либо мои тиммейты играли в свою личную доту, где главная цель зафидить поэффективнее.\n\nСтарик выдает, пожалуй, лучший реген маны в игре, который я видел, через третий скилл, и еще кд способностей уменьшает. На линии мы с тиммейтами сидели с полной маны и отлично себя чувствовали, наяривая друг другу в кустах.\n\nПервый скилл у деда знатный. Лошади сметают всё на пути, проблема лишь в том, чтобы попасть в соперника ибо убежать от этой хуйни проще простого, поэтому либо из кустов гнал табор, либо под стан. Ульта приятно улучшает задувку, позволяя использовать ее в отрывы от героя. Аганим дает прикольную тему с гипнозом, но я, походу, ставил её через жопу, потому что после первого же гипноза все просто убегали.\n\nМне не удалось получить коннект с героем. Дед сам по себе сильный, бьет так, что яйца под ним дрожат, но в моих руках получается чистый кисель. Не вышло у меня реализовать этого пенсионера даже на десять процентов, поэтому старик получает бронзовую медаль Габена."},{"k":"caption","t":"У кого какой уровень? как всегда говно"},{"k":"caption","t":"Моя первая игра на никсе. Как же приятно с инвиза взрывать жопу снайперу было. Но все равно проиграли((("},{"k":"caption","t":"сф конечно разьебывает все вокруг, но и я не отставал"},{"k":"caption","t":"Вот и рейтинг открыт. Что за жетоны поиска? Я что не могу выбрать роль которую я хочу?"},{"k":"caption","t":"Всех с праздником"},{"k":"post","t":"Мужчины, феи, ублюдки, лапочки. Пожалуйста, если со мной просите поиграть, не ливайте если катка вам не заходит. Ибо так вы подставляете не только меня, но и людей которых я пригласил. Так уже было несколько раз.\n\np.s. у нас были все шансы на победу, марс бы вытащил"},{"k":"caption","t":"Одна из интересных каток, почти два раза не проебали, даже я ахуел от рубика"},{"k":"caption","t":"вот сама катка"},{"k":"review","t":"Nyx\n\nГерой как заноза в заднице, вроде вокруг всё тихо и откуда ни возьмись вылетает пиздюлина, и ты уже летишь на фонтан. Вот примерно так я себе его и представляю.\n\nНа линии мне было тяжело стоять против ренджевиков, потому что они меня очень сильно пробивали. Поэтому я аккуратно старался из кустов давать стан, чтобы мне сраку не подпалили. Но терпеть приходилось недолго, как только я получаю 6 уровень, герой раскрывается другими красками.\n\nЭто первый герой, на которого я не покупал аганим. Он даёт способность, где ты можешь закопаться под землю, оставив только одну жопу. И это не бдсм наклонности жука, там реально даётся защита и тд. Но как будто за эти деньги есть предметы, которые дадут больше импакта.\n\nНа жуке можно очень быстро передвигаться по карте, что позволяет либо быстро загангать какую то линию, либо пропушить её, хотя не всегда это получалось.Он способен очень быстро забирать одиночные цели, инвиз - стан - дагон и второй скилл. Но проблемы начинаются, если противников двое, мне либо убегать, что не всегда удаётся, либо драться руками, но чаще это заканчивается смертью. Надо будет посмотреть, что делают опытные игроки на нём.\n\nГерой, как мне кажется, очень хорошо подходит на 4 позицию, чтобы наводить суету на карте и напрягать линии. Он заслуживает золотого Габена. А дальше у нас сопля в виде шара, на котором я вообще не ебу как играть."},{"k":"caption","t":"Играю на виспе, бля это такой позор ебаный"},{"k":"caption","t":"Первая игра, нехуя не понял, меня просто по кругу пускали"},{"k":"call","t":"Кто поиграть хочет? в турбач, на расслабоне"},{"k":"post","t":"Вторая игра на сосалке, сосу у героев и у вражеского тинкера. Он просто 1 всю нашу команду гнобил, что сф сломал шмотки и плакал в таверне всю игру.\n\nТинкер сам говорит, что рейтинг у него всего 4.6к, просто мы молокососы ещё и на место нам в turbo"},{"k":"caption","t":"Третья игра, немного лучше получается сосать."},{"k":"caption","t":"У меня тут небольшой юбилей, 500 подписчиков на ютубе, 2500 в тиктоке и 6 на твиче (кто вы вообще?)\n\nСпасибо всем, кто смотрит этот цирк, дальше хуже!"},{"k":"review","t":"Висп\n\nС первых минут игры мне герой вообще не понравился. Вроде по геймплею все просто, соси себе спокойно у кора, накидывай 3 скил и кайфуй. Но либо керри у меня было на голову ебнутые, что мало вероятно. Просто я , как обоссаный играл на герое.\n\nПервые игры были настолько позорные, что дота сама нахуй вылетала посреди матча. Я сосал абсолютно у всех. Хуже в этом мире никто не отыгрывал на этом герои. Счет 0 на 10 это гарантия качества, что я все тот же безрукий долбоёб.\n\nУльт наверно один из невьебенных способностей, где ты можешь просто нехорошего тиммейта отправить на фонтан, чтобы он поразмыслил о своём поведении. Но я так пока еще не делал, хотя желание было. Если серьёзно, я ульту только пару раз использовал, и то в случаи, чтобы керри восстановился на фонтане.\n\nВозможно, на нём можно и как-то самому драться, условно через 2 скилл, но я был просто присоской для своего керри, создавая условия, чтобы он убивал все что движется. И вот такой геймплей вообще не для меня. Мне больше нравится самому нажимать кнопки, влетать, давать станы, делать какие-то грязные вещи, например дрочить на союзников и соперников, и на Габена, бля понесло меня, сорри. Хотя кто вообще до сюда дочитает.\n\nКак говорится, мурашки на яичках не вылезли на этого персонажа, и он получает бронзового габена, а мы идешь дальше - нахуй","g":1},{"k":"caption","t":"В первый раз мне сказали что я бустер и купил аккаунт...\n\nПо поводу обучение в лс, 1 час стоит 4 млд евро и анальный досмотр"},{"k":"caption","t":"Первая игра на быке, фидил во все тяжкие. Даёшь станы, а потом они всей толпой тебе жопу разрывают. Печально..."},{"k":"caption","t":"28 минута, мой керри"},{"k":"caption","t":"Не ну это пизда... А вот если в рейтинг такие попадутся?\n\nтакие конченные, как я"},{"k":"call","t":"Кто в all pick пойдёт, надо 3 мужчины с железными яйцами"},{"k":"caption","t":"Первый раз играл на керри. Они меня заставили идти, я не виноват"},{"k":"caption","t":"наугад героя взял..."},{"k":"caption","t":"не подвел..."},{"k":"caption","t":"На любимом рубике так нафидить, позор, бан жопы на 2 года. Бруда меня всю игру от моего туза не могла отцепиться."},{"k":"caption","t":"Я что-то не понимаю почему я лучший, я ведь умирал кучу раз, как дота считает кто лучший?"},{"k":"caption","t":"как же я часто умираю на герои, они как будто видят корову и толпой бегут, чтобы порвать мохнатую сраку"},{"k":"caption","t":"Вот такая красота падает на 60 уровне. Любим Габена...."},{"k":"call","t":"Кто готов в all pick рвануть?"},{"k":"caption","t":"Мы идем 5 на 5 с подписчиками, нужно еще 4 тела"},{"k":"caption","t":"Мы если что все в дс, заходите если что"},{"k":"caption","t":"1 против 9 играл"},{"k":"caption","t":"поиграли немного"},{"k":"call","t":"Кто хочет 5 на 5? надо 4 чела, лобби называется и ЛОХИ , регион СТАГОЛЬН"},{"k":"caption","t":"Всем спасибо за игры, как-то повторим"},{"k":"caption","t":"Только такие сообщения и читаю, продолжайте…"},{"k":"review","t":"Шейкер\n\nКогда я играл на этом герое, мне казалось что враги фокусят меня постоянно. Где бы я ни был, в меня всегда влетели два три героя. Из-за этого играть было реально тяжело. Но криво косо я всё равно старался держаться достойно.\n\nДо блинка и после это вообще как будто два разных героя. Пока ты на своих копытах добежишь, тебя уже разнесут. Совсем другое дело когда ты просто появляешься из ниоткуда и на голову падает мохнатая жопа, которая за пару ударов отправляет всех в таверну. Красота...\n\nСкилы у него все приятные, но первый мне зашёл больше всего. Спасти своего кора, да без проблем, стопнуть убегающего лоу противника вообще легко, перекрыть путь врагам тоже пожалуйста. Главное конечно попасть скилом. Ульта тоже очень мощная, особенно когда враги кучкуются. Влетаешь, даёшь ульту и сразу первый скил, и там уже почти без шансов для них.\n\nАганим мне вообще дико понравился. Можно сидеть в засаде как ниндзя, выпрыгивать и раздавать автографы всем подряд.Герой сильный, контроля куча. Единственное надо научится стоять против дальников, потому что это прям больно. В итоге я вручаю ему золотого Габена."},{"k":"caption","t":"Приодел по бомжатски этого мужчину и будем фидить"},{"k":"caption","t":"Как будто в all pick с ботами играли..."},{"k":"caption","t":"Мало того, что отправили на мид, так еще и фидить заставили..."},{"k":"caption","t":"Мне тут посоветовали гуру маркетинга и привлечение народа схему - тип люди приглашают своих знакомых, а ты им что-то. Поэтому погнали."},{"k":"post","t":"Кто приведет одного знакомого получить нихуя. Кто приведет двоих - двойной нихуя. И супер позиция, приведи сто миллионов и получи мой микро член в директ и огромный НИХУЯ","g":1},{"k":"caption","t":"Вот так дружно с подписчиками фидим. Будь как мы"},{"k":"review","t":"Веник\n\nЭтот харкающий ублюдок гнобит любого на линии. Накинул своих мелких рабов и они всю работу за меня сделают, а тем временем я могу одной рукой дрочить габену, а другой щекотать яйца. Так вернёмся к игре.\n\nСкиллы у него все мерзкие и противные для противника. Например змейки, которые захаркают тебя с ног до головы, я знаю что ты это любишь, но мы опять же про игру говорим. А еще они как варды работают и помогают фармить.\n\nВторой скилл вообще имба какая-то , если чувак не следит что на нём висит и начнём бить кого-то, то просто на глазах потухнет. Ульта это чума. Кинул на одного, а страдают все. Ты просто заражаешь всю вражескую команду сифилисом и довольный убегаешь. Аш общагу вспомнил...\n\nНо мне не хватило ему мобильности. Но с ней возможно это тварь вообще будет неубиваемая. Герой сильный, но позиционку держать не забываем. А то нас нашими же змейками отрахают. Веник получает золотого Габена."},{"k":"caption","t":"Кто играл в вов знают там есть разбойник, вот такая же крыса ебанная"},{"k":"call","t":"Кто пойдет играть?"},{"k":"call","t":"Есть что заходите в лобби - ЛОХИ, соберем банду"},{"k":"caption","t":"Вторая игра на бх показала,, что я еще говно скисшее"},{"k":"post","t":"В последнее время две крайности, либо в нашей команде несколько ботов и мы сосем, либо у соперников боты, и они сосут. Что-то габен мутит видимо, очередь сосания какая-то"},{"k":"caption","t":"Кто бы ты не был, спасибо за аркану, буду фидить в максимальную силу на огре"},{"k":"call","t":"Нужно 2 чела в all pick"},{"k":"caption","t":"Гений, миллиардер, плейбой, филантроп…"},{"k":"review","t":"БХ\n\nЭтот мелкий цыган оставит вас без трусов еще во время драфта. Каждое очко тщательно проверяется на золотые монеты. Поэтому играл я на нем всегда голый, да кому-то это может и не понравиться. Но у меня таких нет подписчиков. Я родился в год крысы, поэтому у меня есть коннект с этим героем. Но он хотя бы красивый с большой валыной. И так давай те к игре перейдём.\n\nЕсли кто играл в wow, то герой очень похож на разбойника. Уйти в инвиз и уже оттуда промышлять своими теневыми делами. Я играл через пассивку, пытаясь как можно чаще бить противника, чтобы он не расслаблял булки. Часто бегал во вражеском лесу ставил свои варды и снимал их, чтобы моя команда чувствовала себя великолепно.\n\nНо герой более командный, ибо из урона у меня только 1 способность сюрикен и сама пассивка. Поэтому я старался палить одного противника и звать своих парней чтобы надрать задницу, и часто это работало. Самому цель забрать при равном фарме у меня не получалось, как будто слишком мало урона было.\n\nЯ посмотрел как на нём прошники играют, там вообще разьеб. Эта крыса по всей карте как обосранная бегает и всех кашмарит. Но как выше написал, важно играть в команде, чтобы координировать всех. А так получалось, что в одной игре я отыгрывал хорошо, в другой прям отсасывал. При том что делал плюс-минус одно и тоже. Но то никто гангать не идет, то кто-то афк ушел, то я хуйню какую-то делаю. Ну паблик- что сказал. Но вот вчера с подписчиками на бх отлично поиграл. Все были в чате и быстро забирали цели загулявшие.\n\nУ герой есть свой вайб. И он достоин золотой медали габена.","g":1},{"k":"caption","t":"Когда-то тут будет мое рабочее место, а пока только сральник для работников, удобряют так скажем…"},{"k":"caption","t":"Как вы играете с этими ебанными саппортами? Которые вард не могут даже бесплатный купить и поставить..."},{"k":"caption","t":"Скаймаг прогнал меня на мид, сказал что он пиздатый саппорт..."},{"k":"caption","t":"Лучший вард на сапе. Консультации в говновозе провожу, запись голубиной почтой.."},{"k":"caption","t":"Моя первая игра на герои. Игра была с подписчиками, поэтому тут чил был, надо игры в соло поиграть. На первый взгляд герой прикольный"},{"k":"caption","t":"С праздником. Кушаем шашлык, отдыхаем и фидим по крупному."},{"k":"caption","t":"30 минута, мой мидер решил идти танковать, он не афк если что, даже в чате нас хуесосит"},{"k":"caption","t":"Вот игра с рандомами сразу радует глаз. И даже чувства, что я не совсем конченный появляться стало"},{"k":"caption","t":"Мы играли играли и проиграли, во всем виновата врка, мразь ебанная..."},{"k":"call","t":"Кто в all pick?"},{"k":"call","t":"В лобби 5 на 5 надо 2 чела, лобби ЛОХИ - стагольн"},{"k":"review","t":"Windranger\n\nПервым делом я получил арканы, чтобы дрочить на неё, пока она в таверне. Хорошо, что в таверне я был не часто. Но мозоли все равно натёр.\n\nЕсли смотреть на про трекере её общий процент, то он не супер большой от 47-50% на саппортах. Хотя у не есть все для 4 позиции. Ганг потенциал, быстро пушить башни, контроль и конечно быстрые ноги, ведь у героя мало хп и любой саппорт с двух ударов своего члена, отправляет на фонтан рукоблудить.\n\nНа линии стоять очень комфортно, но если у противников много станов тут начинаются проблемы. Но зато убежать от меня очень сложно. Второй скилл догонит кого-угодно, главное чтобы я нормально попал им.\n\nС помощью ульты не только можно героев испепелять, но и башни. Что дает еще один плюс в копилку герои. Я думаю, что до сюда никто не читает. Ибо нахуй читать, если можно не читать. Но если ты дочитал, то ты пидр. Я все сказал. Но есть важный момент, во время ульты ты по сути привязываешься и фокусишь одну цель, и если в этот момент тебя ловят любым контролем, всё, ты труп.\n\nЕсли смотреть, что покупает другие на врку, можно заметить, что никто не берет аганим и шард. Хотя способность от шарда, может спасти жизнь в определённых ситуация. Возможно это не стоит того и лучши купить что-то получши. Лучше спросить опытных игроков на герое об этом.\n\nУ меня стоял выбор между алмазным и золотым габенам. Но как будто чего-то не хватает до алмаза. Поэтому он получает золотого Габена и немного капелек пота от мамаши Габена. Я уже хуйню несу полную, это потому-что я приболел, отписка и бан каналу.","g":1},{"k":"caption","t":"На линии стоять как будто отдыхаешь, способности пол ебало взрывают"},{"k":"caption","t":"Что думаете на счет этих легендарных скинов"},{"k":"caption","t":"Взял этого мужика, устоять от такой сраки я не смог"},{"k":"caption","t":"Подавать команду или не стоит забирать у них первое место?"},{"k":"caption","t":"Я хз почему первым делом не убивают петуха. Ибо 1 прокаст и там пиздец просто"},{"k":"caption","t":"Первый раз попалось в рандоме, что все тимейты в тиме были, как одна команда. По войсу дали инфу, заберали рашана, торментора и в целом игра прошла по кайфу."},{"k":"caption","t":"Внимание, сейчас подписчик скинуть фотку свою с пенисам, это не учебная тревога, готовте салфетки, латекс и носок.\n\n@user мы ждем"},{"k":"caption","t":"К сожалению это была ложная тревога. Мы так не увидели мужской писюн. Я думаю ваше сердце, как и мое разбито. Мы это так не оставим!"},{"k":"caption","t":"Моя типичная тима, кто первый угадает про что будет новый рилс получит какую-то хуйню от меня. Этот кадр будет там...\n\nникто не угадал тыц пыц"},{"k":"caption","t":"Эх никто не угадал, но троим попытавшиеся дам какой-то подарок, я свяжусь с вами"},{"k":"caption","t":"Габен пидр. 30 дней ждать чтобы подарок отправит, это грустно"},{"k":"post","t":"Блядь какой я конченый уебан доверчивый. Как лоха пытались развести, но на что надеялись хз. Но все же всех друзей со стима я потерял и комментарии ( там мне рецепт от простаты написали, жалко его). Так что буду знать, что бывает и такое. Кто хочет, может заного добавляться и да, я еще более конченный, чем думал\n\nТак что добавляйтесь, кто хочет - 337578062"},{"k":"caption","t":"Мне тут доложили, что вы не знаете про мои видосы большие. Вот вам про бару и пуджа. В конце каждого есть прекрасная песня.\n\nПУДЖ - <ссылка>\nБАРА - <ссылка>"},{"k":"caption","t":"Мне тут накидали легендарные песни, я обязан с вами парочкой поделится .\n\n<ссылка>\n<ссылка>"},{"k":"caption","t":"Петух\n\nТут будет мало текста ибо петух есть петух. Все всё знают, сильно бьет, боится контроля, но скучноват. Серебреная медаль будет ему в самый раз"},{"k":"caption","t":"Всю игру керри просто по деревьям прыгал, может я тоже так хочу..."},{"k":"caption","t":"Если вы также не будете фидеть, даже не зовите меня играть"},{"k":"caption","t":"Вот это я понимаю инвокер, всю игру тащил, но в команде у него я, поэтому всё равно проебём"},{"k":"caption","t":"Если увидите игрока на чене, в бан нахуй отправляйте. Всю катку руинил, пидарас ебанный"},{"k":"caption","t":"Это прям закономерность, когда хочешь поиграть на герои, он почти всегда в бане. Вот так вместо чена, пришлось на рубэне фидить"},{"k":"caption","t":"Габен крутит"},{"k":"caption","t":"Рождение будущей ЧСВ"},{"k":"caption","t":"Чен в соло"},{"k":"caption","t":"Чен в соло 2...\n\nДумаю начать коуч по чену делать."},{"k":"review","t":"Чен\n\nКаждый день кто-то обязательно напишет, чтобы я поиграл на нём. И я поиграл. И конечно же делал катки в соло. Поймите кого-бы я не взял, всегда будут катки фидится в соло. Этой практики я обучался с рождения. Меня никто не перефидит.\n\nГоворят, что у него сложное микро, ведь у каждого крипа есть свои скилы, статы. Но ведь мы можем просто не использовать их. У нас в арсенале есть еще 4 героя, а ты просто можешь играть в прятки со своим зоопарком. И после этого понимания играть на чене было настолько просто, что после каждого матча 9 репортов летели ко мне с молниеносной скоростью.\n\nСложнейший герой в моих руках превратился в самого простого и легкого персонажа. И из-за того, что он такой просто мы отправляем ему бронзовую медаль габена.\n\np.s. после игр в соло на чене, стало поступать много предложений об обучении. Пока к сожалению не могу, потому что сейчас тренирую таких киберспортсменов как TORONTOTOKYO и в целом несколько команд заказала полное обучение на грядущий интернешнл","g":1},{"k":"caption","t":"Козырный скин. Покупать ли его? а может с сокровищницы достать, но габен зажмет его. Или пошел скин нахуй, мы будем чисто на скиле фидить"},{"k":"caption","t":"Пиздец вы заговняли образ, пришлось свой делать"},{"k":"caption","t":"Поиграл с подписчиком, мой бойцы никогда не подводят, с хускаром мы поговорим, а то нам всю картину портит"},{"k":"caption","t":"Я нашел себе учителя, цмка просто продала все шмотки, купила ботинок и бегала на фонтан фидить, мне еще есть куда расти"},{"k":"review","t":"Пальчик в анальчик, один из самых популярных героев получает золотого Габена. Ибо сосать я могу теперь не только в жизни"},{"k":"caption","t":"А это нормально,что сапы так бьют много, я 5 был"},{"k":"caption","t":"Кто знает, откуда кадр — к тем вопросов нет. Остальные, учите матчасть\n\nСкоро на ютубе..."},{"k":"caption","t":"В видео ответил на некоторые вопросы про рейтинг, члены и тд. Обязательно послушайте песню в конце Смотрим, дрочим и наслаждаемся.\n\n<ссылка>"},{"k":"caption","t":"Зомби норм, но стана не хватает ему как-будто. Играю через ауры, хз правильно это или нет"},{"k":"caption","t":"Вот эти двое в инвизе меня прям заёбывали, но моя армия дохляков грызла их за ляжки"},{"k":"caption","t":"Мертвец с армией оказался достаточно приятным, но скучным. Серебреная медаль отправляется к нему."},{"k":"caption","t":"Первая игра в рейтинг, пока полет нормальный"},{"k":"caption","t":"Любитель делать язычком всякое..."},{"k":"caption","t":"Играю в рейтинг счет 0-8 , пизда... , тут потно что-то , мама забери меня обратно"},{"k":"caption","t":"Это рейтинг детка, тут тебя ебут без смазки, но мы терпим"},{"k":"caption","t":"ну тут без комментариев...."},{"k":"caption","t":"Урвал рубика наконец-то"},{"k":"post","t":"Вот рейтинг это прям сказка, мидер всех матерей наших вспомнил, нежным именем их назвал и указал кто мы такие...\n\nя нашел место, где настоящие мастера слова, мне тут нравится"},{"k":"review","t":"Ларго, мужчина, который умеет делать язычком всякое. Персонаж мне не сильно зашел по его механики. Он в моем рейтинге получает бронзового Габена."},{"k":"caption","t":"Заметил в рейтинге каждый пытается доказать, что он играет лучше чем кто-либо, по крайне мере он это слюной у рта в микро орет","g":1},{"k":"post","t":"4 подрят луза, габен опустил меня к опущеным, где мне и место. Если у меня немного жопа напекает, я не представляю как у вас бывалых она полыхает.\n\nНо с другой стороны это кайф, когда хочешь нахуй выломать монитор... обожаю"},{"k":"post","t":"Это пизда. Соперники как будто знают где мы находимся, всегда куда бы мы не шли, нас сразу же ловят. Варды только поставил, через минуты его палят. Похоже я уже ебнулся... одни лузы продолжают, я попал в самую жопу"},{"k":"caption","t":"После дней лузов, решил сделать паузку. Забухал, в итоге еще и обоссался. Решил на энигме пойти в all pick, но и тут обосрался."},{"k":"post","t":"Вечером спокойно решил поиграть каточку. Кстати заметил после игры в рейтинг, в all pick стали попадаться чуваки с рейтингами от рыцаря. В этой игре 9 рыцарей и 1 синий недорекрут"},{"k":"caption","t":"Это проклятье уже не остановить"},{"k":"caption","t":"рейтинг лучшее место"},{"k":"caption","t":"А могли победить... Но мы в черном списке Габена"},{"k":"review","t":"Энигма, синий мужчина с огромными глистами, которые разбивает всеми лица. Герой мне кажется очень командный, ибо если ульта ушла в никуда, то выключается герой с игры. Энигма получает золотого Габена."},{"k":"caption","t":"100 квартеро пройден, получите говно и распишитесь. А у вас какой уровень?"},{"k":"caption","t":"Продолжаем нашу серию лузов"},{"k":"caption","t":"Играй хорошо, играй плохо, но поражения всегда стабильно."},{"k":"caption","t":"Что-то я пока не понял героя, надо пару гайдов глянуть, как на нем нагибать"},{"k":"caption","t":"Вот что делать, если у тебя керри просто 0-10 идет, а когда таких керри два?"},{"k":"caption","t":"Стабильно только в низ"},{"k":"caption","t":"Ебать, это было сложная долгая игра, посмотрел гайды на героя и чет решил сразу в рейтинг на нём. Ёбнутый ли я? ДА!"},{"k":"caption","t":"Как вам новое событие и новый патч? Лутанем аркану с 5 лвла?"},{"k":"caption","t":"Ну когда-то победы должны быть"},{"k":"review","t":"Гримстроук\n\nГерой, которого я не разу не встрачал в катке. Либо герой не популярный, либо мне просто не везло играть с ним или против него.\n\nМужик с кистями мне очень понравился, я сначала хотел его в золотые яйца габена его опустить, но мужик достоин большего. И по самые яйца он получает алмазного Габена!"},{"k":"caption","t":"Только была победа и тут говна лопаты держи"},{"k":"caption","t":"Теперь за меня бустак... Баланс"},{"k":"caption","t":"Давно мы не играли вместе, кто в турбо/all pick пофаниться? Через 12 танго будет нагибать всех"},{"k":"caption","t":"29%, следующая катка решит всё, ваши ставки господа."},{"k":"caption","t":"Много это или мало решать вам"},{"k":"caption","t":"И это, какой нахуй визаж, давайте за шамана голосуйте"},{"k":"caption","t":"Визаж конечно всю игру нам заруинил. Увидите такой ник сразу репорт!"},{"k":"caption","t":"Что вам упало? мне как всегда говно"},{"k":"caption","t":"С утра решил в рейтинг заглянуть"},{"k":"caption","t":"Вот так дота и держит в заложниках нас"},{"k":"caption","t":"понемногу двигаемся к стражам"},{"k":"caption","t":"Готовимся с командой к интернешену. Думаете есть шанс, что мы не возьмем 1 место?"},{"k":"call","t":"Кто в рейтинг пойдёт сливать ммр? группа титанов ждет именно тебя."},{"k":"caption","t":"Поиграли крч, возможно играть с рандомами не сильно плохая идея"},{"k":"call","t":"Кто хочет в рейтинг пойти? 3 тела над"},{"k":"caption","t":"команда мечты собралась, впереди интл и миллионы говна"},{"k":"caption","t":"это чтобы вы понимали, мы готовы к инту на 100 процентов, это 15 минуты"},{"k":"caption","t":"Ну легенды, запомните этих героев"},{"k":"caption","t":"Такие пироги"},{"k":"caption","t":"Ну тут ребятам еще работать и работать, что бы умело фидить. Я их научу"},{"k":"review","t":"Визаж со своими гаргульями получает серебреного Габена. Герой сложноват, но со второго скила ебала разваливает нормально."},{"k":"call","t":"Кто готов жестко в рейтинг? Есть одно правило, кто делает первое убийство ломает шмотки. Играем на жёсткий проигрыш."},{"k":"caption","t":"Поиграли немного и как всегда проиграли"},{"k":"post","t":"За меня попал бустак, он как будто с детьми играл. Общительный парень, на основе 15400 говорит имеет.\n\nНа funpay даже ссылку кидал в общий чат. Хз нах платить за рейтинг, если он все равно в игре ничего не значит."},{"k":"caption","t":"Одну проигрываю, одну выигрываю, получается бесконечный рекрут."},{"k":"call","t":"Кто готов в рейтинг на победу?"},{"k":"caption","t":"Нужен 1 в рейтинг"},{"k":"caption","t":"Парни как всегда не подвели. Угадайте кто мидер?"},{"k":"caption","t":"Играя с вами слил 150 птс. Только вниз только назад. Вы никогда не подведёте меня. Худшие из худших. Дальше меньше"},{"k":"caption","t":"Улитки прикольные"},{"k":"caption","t":"Ульта у мужика конечно мое почтение"},{"k":"caption","t":"На стиле проиграл"},{"k":"caption","t":"Понемногу растем, у вас там как с порядой?"},{"k":"caption","t":"Ваши ставки, кто кого"},{"k":"caption","t":"Сука ну рубик пидарас ебаный, всю катку слил"},{"k":"caption","t":"Кто кого? я ставлю, что нам пизда"},{"k":"caption","t":"Ну что сказать, учимся играть"},{"k":"caption","t":"Стабильно в низ"},{"k":"caption","t":"Смотрите как рекрут трахать будет рыцарей"},{"k":"caption","t":"Рыцари в нулину трахнуты"},{"k":"caption","t":"Кто тут сильней? я кстати уже умер"},{"k":"caption","t":"Собрал бойцов и через дс давал им команды как проиграть, но они меня не слушали"},{"k":"caption","t":"Как вам?"},{"k":"review","t":"У нас у обоих есть вич, но мы все же разные. Герой медленный, но жопу разрывает. Он получает золотого габена"},{"k":"caption","t":"Бля тут легенда рыцари, трахну их"},{"k":"caption","t":"Так этих мужиков"},{"k":"caption","t":"Ваши ставки?"},{"k":"caption","t":"Крч, чуваки ливнули в начале игры и рубик в соло всю катку спас. Пора бустить акки"},{"k":"caption","t":"Решил на ночь в соло пойти, чувствую жопа будет в дыму..."},{"k":"caption","t":"обидно"},{"k":"caption","t":"Говорят за победу больше ммр стали давать. Это правда? У меня пока не пишет сколько дают и отнимают"},{"k":"caption","t":"А бабка да дает жару, правда медленная какая-то"},{"k":"caption","t":"Поиграли с подписчиками, учил играть молодых"},{"k":"caption","t":"Что по обнове, когда планируется, есть сливы уже?"},{"k":"review","t":"Бабка, сейчас её берет каждый мидер, либо она в бане. Но мне удалось пощупать за её пенсионные бочка. Герой прикольный и золотой габен летит к ней"},{"k":"caption","t":"что будем брать"},{"k":"caption","t":"Поиграл с подписчиками, ну если бы не воид, то были бы шансы. Но обязательно должна быть руина в катке."},{"k":"caption","t":"Так зачастил я играть с подписчиками, открываю неделю соло рейтинга. Сейчас у меня 491птс, как думаете опущусь до 200?"},{"k":"caption","t":"Ну что побегаем"},{"k":"caption","t":"Так и знал, что нужно было брать светлое"},{"k":"caption","t":"Ваши ставки"},{"k":"caption","t":"Походу против меня мои подписчики собрались. Ну вы конечно хитрые"},{"k":"caption","t":"Я бы мог не показывать вам такого, но я хочу выебываться"},{"k":"caption","t":"Крч я гений игры, когда марси ультует я её прятал в шкаф. Только благодаря моему скилы, мы 4 vs 5 победили"},{"k":"caption","t":"Это что? как также сделать?"},{"k":"caption","t":"Даже килы не смог стилить"},{"k":"caption","t":"Ебать обнова, я срать"},{"k":"caption","t":"Как думаете стоит снимать видосы по обнове? Как я все открываю, покупаю все скины и тд? Или и так дохуя этого будет"},{"k":"caption","t":"С подписчиками в турбо набивали себе билеты. Какой у вас уровень уже?"},{"k":"call","t":"Кто в турбо пойдет билеты фармить, на победную идем"},{"k":"caption","t":"Зашел к героем и показал, что они для нас (рекрутов) просто пыль"},{"k":"caption","t":"Любитель хлыстов, острых ощущений и конечно же ебли в жопу. Истинный искусник движения гачи. Он один из нас."},{"k":"caption","t":"Немного закупился, скоро покручу сокровищницу, а потом уже по открываю лавку"},{"k":"caption","t":"Упало башка с 13 крутки, Чтобы все скины получить понадобилось 30 круток"},{"k":"caption","t":"Попробывал вашего бэйна, получил пизды"},{"k":"caption","t":"Все забыли про квартеро, а я напомню. Там стабильно падает говно"},{"k":"caption","t":"Что этот парень на рекрутах забыл..."},{"k":"caption","t":"В лавке выпал такой мужик, стоит брать? с бесплатной крутки"},{"k":"caption","t":"А герой то имба"},{"k":"caption","t":"Продолжаем покорять рейтинг, пока еще рекрут, но дальше меньше"},{"k":"caption","t":"Тренировались с подписчиками к инту. Ещё немного не дотягиваем. Но на 90% бойцы готовы"},{"k":"caption","t":"Ну с этим парнем все ясно. Любит поднимать всех за яйца"},{"k":"caption","t":"Что за псина мне упала? Даже цены нет"},{"k":"caption","t":"Первый раз встретился с дебустерами. Чуваки с 0 просто специально умирали"},{"k":"caption","t":"У нас бейн ульту в паука бруды дал. Скрытая мета"},{"k":"caption","t":"Поиграл на дереве, просто деревом был. Вот бейн, мидер через паучков играл"},{"k":"caption","t":"Растём по немногу"},{"k":"caption","t":"Вот такое выпало как вам"},{"k":"caption","t":"Вы не заметили, что в рейтинге стало проще играть. Все как будто в турбо потные ушли"},{"k":"caption","t":"Немного решил лавку пооткрывать"},{"k":"caption","t":"2 аркана в копилку"},{"k":"caption","t":"Как тяжело с этими курьерами, я хз какие стоит пропускать, а какие брать . Вот этот мелкий пездюк выглядит норм"},{"k":"caption","t":"Решил сундук октрыть"},{"k":"caption","t":"Это точно редкий вард или пиздешь какой-то?"},{"k":"caption","t":"Наконец-то именно это я ждал, как думаете что упадет?"},{"k":"caption","t":"Сюда нахуй, вот и покрутили. Я впринципи брал то, что мне нравится. Ибо я хз как оценивать, если условно нет цены"},{"k":"call","t":"Кто хочет поиграть? Можем голой жопой по турбо пробежаться или потная ебля в рейтинге."},{"k":"caption","t":"В турбо 2 место есть жестко проиграть"},{"k":"caption","t":"Подскажи а подарочные карты стим в рф работают? Условно если я отправлю вам подарочную карту стим (молдова), вы сможете ее принять ?"},{"k":"caption","t":"Раздал стиля","g":1},{"k":"caption","t":"Раздал стиля 2"},{"k":"caption","t":"Раздал стиля 3"},{"k":"call","t":"Кто в рейтинг раздать стиля?"},{"k":"caption","t":"Раздал стиля 4"},{"k":"caption","t":"Раздал антискил"},{"k":"caption","t":"Раздал антискил 2"},{"k":"caption","t":"Раздал стиля 5, надеюсь так и до рыцарей дойду"},{"k":"caption","t":"Габен доту сломалэ"},{"k":"caption","t":"Лично договорился с габеном чтобы сларку дали лучшего"},{"k":"caption","t":"Дерево мне не зашло. Возможно это все из-за флешбэков, ибо в меня то же часто семя входило"},{"k":"caption","t":"Габен балует"},{"k":"caption","t":"Че цены нет? норм или нахуй его?"},{"k":"caption","t":"Ограбил габена"},{"k":"caption","t":"Ограбил габена 2, у меня уже есть она"},{"k":"caption","t":"Герой прекрасный, правда путаюсь в кнопках"},{"k":"caption","t":"Все забыли про квартера, я напомню, тут как всегда говно"},{"k":"post","t":"Я и не думал, что на санного ноунейма подпишется более 500 человек. Это как населения моего мухосранска. Давно у нас розыгрышей не было, пора это исправлять и вводить их на регулярной основе. Спасибо каждому, что гнобите меня и каждый деть желаете сдохнуть и удалить доту. С помощью вашей надежды я теряю рейтинг и смысл к жизни. Вы делаете меня хуже. Люблю вас","g":1},{"k":"caption","t":"Ставь реакции и может именно ты будешь поцелован прямо в свой цветочек"},{"k":"post","t":"Думаешь отделаетесь одной трещиной?\n\nДавайте разыграем 5 автоматонов и 2 арканы на выбор (которые можно купить в доте)\np.s. - первые 2 места, которые выберет бот получит по аркане, остальные по автоматону\n\nКонкурс заканчивается через неделю - 20 числа"},{"k":"caption","t":"Это была пиздец какая долгая, но интересная катка."},{"k":"caption","t":"Пошла полоса ебали в сраку"},{"k":"review","t":"На вид обычная феечка, но стоит из трусов достать орешник, так все ахуевают. Она получает алмазного габена.\n\nГерой мне очень зашел, а потом и отчим в меня зашёл..."},{"k":"caption","t":"Ахуенный лучший игрок"},{"k":"caption","t":"Герой душка, одно рукой дрочишь, второй рукой тоже дрочишь"},{"k":"caption","t":"С самого утра пришлось трахать всех"},{"k":"caption","t":"Я хотел быть худшим, но я лучший среди худших"},{"k":"caption","t":"Фу блядь, в душе всегда рекрут, теперь я в лиге бичей и бомжей, пора спускаться назад в тьму"},{"k":"caption","t":"Ваши ставки?"},{"k":"caption","t":"Отсосал, но зато счет равный"},{"k":"caption","t":"Бля, кто-то накрутил подписчиков, нахуя? Это все за анальный осмотр?"},{"k":"caption","t":"Получается боты победили. Чисто сам себе накрутил, сам себе очко осмотрел, Гений, плейбой, долбаёб"},{"k":"caption","t":"Скоро удаляться боты все, и сделаем новый розыгрыш среди участников, подключу специальных ботов, чтобы такого не повторялось"},{"k":"caption","t":"Поиграл с подписчиками, страшно очень страшно. Рыцаря слил, в соло опять еду набирать"},{"k":"caption","t":"Пришлось пацанов бустить, то больно смотреть на них"},{"k":"post","t":"Ну что проведем розыгрыш повторно, ибо боты пидарасы и я пидорас. А главное вы тоже пидорасы, надеюсь...\n\np.s. - первые 2 места, которые выберет бот получит по аркане, остальные 5 по автоматону"},{"k":"caption","t":"p.s. розыгрыш сутки будет"},{"k":"post","t":"Меня часто спрашивают, когда стримить будешь? (только бомжиха, которая меня страпонит спрашивает). Тут вопрос, а кто-то будет смотреть? Ибо я скучный залупный отпрыск и вы разочаруетесь, что я просто обосранный саппорт, который нажимает хил в медузу.","g":1},{"k":"caption","t":"Тебя еще не трахнули? Тогда я иду к вам..."},{"k":"caption","t":"Герой для мужиков в латексе, которые пью лате на мендальном и ебуться в жопу только с резинкой"},{"k":"caption","t":"Сбор пидарасов, нужно протестить это говно <ссылка> Ебанная эта обс, то битрейт большой, то пенис маленький"},{"k":"caption","t":"Наконец-то нормальные игроки со мной"},{"k":"caption","t":"Написал всем победителям, чтобы не говорили, что я чмо ебанное кидаю парней.\n\nЗапомните, я кидаю только мужчин в свою постель"},{"k":"post","t":"4 уже получили свои подарки, остальные 3 пока молчат. Разобрался, как нормально отправлять по логину стима бабоcы через apple pay. Всем спасибо за участие. Ну думаю в августе опять розыгрыш надо будет устроить, ибо почему нет. Можем будет прямо на стриме делать это, если конечно позволит мне интернет и obs настрою. Соситесь, пердитесь, ебитесь."},{"k":"caption","t":"Почему-то ночные игры всегда долгие"},{"k":"post","t":"Меня тут умоляет на ладонях один мой подписчик, что бы вы оценили его руководства. Сильно не ругайте, он срал под себя до 20 лет, потом стал срать на себя. Когда его видят, выкалывают глаза. Я с ним играл в доту и на первой минуты, до рун падает вышка в миду (он в миду играет) . А так сборка хорошая, чисто фид и страдание. Все всех люблю, ебу, ласкаю\n\n<ссылка>"},{"k":"caption","t":"ах да, вот тот самый в душе титан, на цифрах рекрут, по жизни петух - @user"},{"k":"post","t":"Запустил твич для тестов чата, а тут зашли люди и пришлось идти первую игру на таске играть. Шариком не долетал, клетку не в того ставил, но рыцарь 2 в кармане. Я полной поддержкой был"},{"k":"caption","t":"Первый раз в квартеро иморталку увидел"},{"k":"caption","t":"На таске против легент пошел, 2 игра - <ссылка>\n\nпобедим нет?"},{"k":"caption","t":"таск в соло"},{"k":"caption","t":"таск в соло 2"},{"k":"caption","t":"Спасибо всем кто был, придумаю награды за балы канала тип может и арканы всуним и в очко мое."},{"k":"caption","t":"Tusk\n\nМорж, который похож на кота. Запирать своих тиммейтов для разрыва туза, пытаться сейвить шариком и умирать. Пинать крипа, а не героя. Это все я"},{"k":"caption","t":"Пойдёмте проходить третью главу\n\n<ссылка>"},{"k":"post","t":"Многие спрашивают, так сколько тебе лет мразь?\n\nСегодня у меня юбилей. Я в том возрасте, когда совать всякое в жопу это необходимость для разогрева простаты. Жизнь коротка и я пытаюсь укоротить её еще быстрее.\n\nСосите пенисы, играйте в игры и оставайтесь всегда рекрутами.","g":1},{"k":"call","t":"Кто с самого утра рейтинг сливать?"},{"k":"caption","t":"Раздал стиля на пудже"},{"k":"caption","t":"А какой смысл с 0 просто фидить? Как будто 1 игрок управлял 5 сразу."},{"k":"caption","t":"Раздал стиля"},{"k":"caption","t":"Пудж срать хотел на ваши медали, да и на вас тоже. Мои хуки это лучшее, что есть. Кто со мной играл тот знает\n\nКогда-то делал видео про пуджа <ссылка>"},{"k":"caption","t":"Первая игра на герои и уже раздал стиля."},{"k":"caption","t":"Стиль набирает обороты"},{"k":"caption","t":"Вечерние катки самые прекрасные . Первый раз вижу, чтобы кери от аегиса отказывался, мы 3 раза убивали рашана и 3 раза джагеру было срать на аегис."},{"k":"caption","t":"Когда девушка в катке этой всегда весело. Как думаете на ком играла она? Вот если посмотреть, то ясно, что на феи играет обосаный мусор"},{"k":"post","t":"Как вам обновление? Они реально взяли и просто перекрасили уже существующие скины? В целом ландшафты понравились и наборы команд, только я ещё не одной команды не знаю ))"},{"k":"caption","t":"Так у меня нахуй полетел телефон. Мой айфон 11 официально умирает, поэтому сейчас пытаюсь выбрать либо телефон либо пробка в жопу."},{"k":"caption","t":"ООО сегодня сбросили рейтинг всем прошником, но забыли про меня походу. Вам как сбросили?"},{"k":"caption","t":"По-немногу в соло иду до героя, пока рыцарь 3 полёт нормальный"},{"k":"caption","t":"Мерзкая мразь, которую каждый хочет убить. Но силенок, не у всех хватает."},{"k":"post","t":"🏆 РОЗЫГРЫШ 5 бандлов!\n\nКаждый победитель сможет выбрать набор команды (золото) или комплект наклеек (золото).\n\n❗️Условия:\n- Подписаться на пидора\n- Поставить эмоджи и нажать на кнопку\n\nИтоги 10 августа"},{"k":"caption","t":"Скоро на ютубе новый ролик, надеюсь успею к пятнице."},{"k":"caption","t":"Так и живем"},{"k":"caption","t":"Что-то меня трахают на пугне вторую катку. Но это не я конченный, а команды\n\np.s. нет я конченный! факт!"},{"k":"caption","t":"Долго выбирал какую команду, в итоги самые нормальные фразу были у тим спирит"},{"k":"caption","t":"Так же взял самую важную фразу. без неё никуда"},{"k":"caption","t":"Что-то не прёт"},{"k":"caption","t":"начинаем сосать и даже причмокивать"},{"k":"caption","t":"Многие просили стрим, я хз зачем он вам, но вот есть пару часиков пойти фидить\n\n<ссылка>"},{"k":"caption","t":"Так получилось, что пришлось идти на мид, я думал все будет хуже, но нет отсосал как всегда. Вот что значит годы тренировок"},{"k":"caption","t":"Вот такие сеты выкатил габен, но мы их не получим"},{"k":"caption","t":"завтра...."},{"k":"caption","t":"Отсосет тебе, отсосет врагу, отсосет крипу. С аганимом сосет всем. Вся как у меня в жизни."},{"k":"post","t":"Новый ролик на канале. Я бы хотел чаще выкладывать ролики, но я не хочу. Кто досмотрел до конца, у того огромные, потные яйца во рту. Приятно просмотра.\n\n<ссылка>"},{"k":"caption","t":"Дальше только вниз"},{"k":"caption","t":"Первая игра на дазле. Немного непонятно ульта, она просто усиливает все способности. Но способности и так сильные, надо разбираться"},{"k":"caption","t":"100 уровень квартеро"},{"k":"caption","t":"Неплохо дазл исполняет"},{"k":"caption","t":"Наконец-то собрал свою команду к инту"},{"k":"caption","t":"С помощью грима ульты всегда понятно где оригинал у пла. Был разработан план, трахать пла при каждой возможности, но я влетал первым и трахали меня"},{"k":"caption","t":"Окрестит бесплатно. Играть на нём достаточно весело, но вот акс пидр"},{"k":"caption","t":"Бля у меня всё в говне, кроме поддержки"},{"k":"caption","t":"Как же акс всю игру трахал меня.... Но вот остальные походу без рук играли"},{"k":"caption","t":"Габен замедляет доту сильнейшему"},{"k":"caption","t":"Ульта прикольная, шестеренки пока непонятно как ими убивать, я просто пути ими преграждаю и всё"},{"k":"caption","t":"я первый раз видел, чтобы снайпер не смог..."},{"k":"caption","t":"Новая рубрика для TikTok на подходе.\nСможете угадать, что за хуйню я придумал?"},{"k":"caption","t":"Всю игру портил настроение инвокеру своей ракеткой"},{"k":"caption","t":"Угадайте кто тут лучший"},{"k":"post","t":"Мне в последние время в друзья добавляются люди божество/титаны. И тут 2 вариант либо понимают, что такому серьёзному человеку апнуть титана будет быстро и уже готовятся со мной сыграть, либо просто понимают, что этот уёбок никогда не дойдёт даже до властелина, пусть посмотрит на профили мастеров"},{"k":"caption","t":"Смотрите инт? Как вам вообще? Я особенно за сапами слежу, иногда кажется, что они у меня учились.\n\nКак ваши фэнтези, угадали со всем?"},{"k":"caption","t":"Рубик чисто пиздил скиллы виверны, кто видел тот видел."},{"k":"caption","t":"85 минут уже, битва как за финал. 4 рапиры по кругу ходят..."},{"k":"caption","t":"Что-то у меня совсем плохо, а у вас как дела?"},{"k":"caption","t":"После просмотра инта, играть хочется ещё более круче"},{"k":"caption","t":"Решил по фану крутануть рулетку, думаю может шейкера выбить и сразу прилетает редкий комплект"},{"k":"caption","t":"Ульта грима + санстрайк и нету двоих"},{"k":"caption","t":"Так я немного пропал с радаров, это потому что моя смена бомжам давать на районе. Как ваши прогнозы? Сколько очков?"},{"k":"caption","t":"Герой очень командный. Влетаешь в кучу врагов, а тимейты говорят, что передумали файтится и тебя ебут по кругу. Это кайф, обожаю"},{"k":"caption","t":"0 игр на герои и уже лучший. Учитесь"},{"k":"caption","t":"Покупаешь гривсы + шард и бегаешь все лечишь, стратегия рабочая. Апарату правда будет похуй на это, но не важно"},{"k":"caption","t":"Я нажал калибровку, что бы набравшись опыта двигаться ко дну. Правда я не знал, что раз в год можно нажимать её. В целом пока полёт нормальный"},{"k":"caption","t":"Все сделали прогнозы? Я делал сам полагаясь на своё чутье, единственное думаю кто победит спирит или ликвид"},{"k":"caption","t":"Понеслась полоса говна, сейчас в катке как будто все пришли учится с моего нового видоса, я ебал . 3 минута счет 0-11 нас ебут"},{"k":"caption","t":"Ну что, вот и прошёл калибровку"},{"k":"caption","t":"Калибровку проходил в соло, в итоге + 700 птс дали"},{"k":"caption","t":"Ну как так можно апаться блядь.. Это просто желе из говна"},{"k":"caption","t":"Короля не убить!"},{"k":"caption","t":"По-немногу начинаю учится фармить сапе, пока моих тимейтов в сраку долбят"},{"k":"caption","t":"Что у вас сколько там? Как видите забрал лучшее у габена, дальше меньше"},{"k":"post","t":"Герой похож на паладина из wow, надеюсь он такой-же заднеприводный. Я его не разу не встречал в катках...\n\nМне не хватило станов, да у него куча бафов, но тебя так же кайтят, как привокзальную шлюху . А таким героям как шадоу демон, вообще насрать на тебя..."},{"k":"caption","t":"Уже с легендами начинаем пиздится, пока полёт нормальный"},{"k":"caption","t":"Что школяры, в школу пиздуете пока мы тут фидим"},{"k":"caption","t":"Цена ошибки очень высока, не так дал ульту словил репорт, не в того дал - репорт. Тиммейты ждут от тебя лучшей игры, даже если и играют как говно"},{"k":"caption","t":"Герой сложный, с сильными кнопками, которые помогают фидить как мразь. И мне это нравится"},{"k":"post","t":"Я тут пропал. Но меня просто бомжи по кругу пускают, такая вот подработка давалкой. Скоро я вернусь в прежний ритм и каждому сделаю осмотр простаты. Кстати, как вам моя рубрика - \"Учу фидить в доту?\", если не смотрели, идите нахуй. Люблю вас","g":1},{"k":"caption","t":"Что-то герой вообще показался сложным, чем-то на чена похож, так же ебаться с этими животными"},{"k":"caption","t":"Често лайнинг пиздец мне сложно даётся на ней, но когда появляется аганим + пика, там герой сам всех пиздет. Надо учится крипами играть норм"},{"k":"caption","t":"Кстати в каждый игре вот такие типы, у вас как? (они в одной команде были)"},{"k":"caption","t":"Мои ученики по закрытому курсу фида. Учитесь..."},{"k":"caption","t":"Что вам упало?"},{"k":"caption","t":"Энчантресс очень сильная, но не в моих руках. Меня даже обосали мои собственные крипы..."},{"k":"caption","t":"У меня была одна задача - рушить башни. Я её выполнил на ура"},{"k":"caption","t":"Пл имба, но не когда он в моей команде. Мидер всю игру тащил, но не хватило"},{"k":"caption","t":"<ссылка>\n\nЯ вас научу играть в доту нормально…"},{"k":"caption","t":"Джакира.\n\nТы можешь быть одноруким, косоглазым цыганом как я. Но все равно вносить импакт команде."},{"k":"caption","t":"Агенты повсюду"},{"k":"caption","t":"Жаль не записал как они в микро культурно обащлись.... Таких ошибок я себе не прощу"},{"k":"caption","t":"Глаз радует пл"},{"k":"caption","t":"Не стоило разбрасываться словами, я уже выдвигаюсь"},{"k":"caption","t":"Птица"},{"k":"caption","t":"Угадай героя по закупу"},{"k":"caption","t":"Что-то никто не угадал"},{"k":"post","t":"Однояйцевый мне понравился. Но он не такой простой. Кайф что можно делать 3-4 стаков одновременно. И любой керри тебе говорит спасибо, но кто сказал что это ему стаки."},{"k":"caption","t":"Что у вас падает что-то вообще?"},{"k":"caption","t":"ну что, полет отличный пока"},{"k":"caption","t":"Готовлю на завтра ролик, сам заболел, возможно чума, всех обнял и жопу ебал"},{"k":"caption","t":"С самого утра решил начать лудить"},{"k":"caption","t":"Арканы не выпало, нужен додеп"},{"k":"caption","t":"Первый пошел"},{"k":"caption","t":"Ну вот и все, 50 из 50. Габен все бабки забрал"},{"k":"caption","t":"Трансформация"},{"k":"caption","t":"Что-то дота сломалась"},{"k":"caption","t":"Я так и не определился куда его послать. Но мне он понравился. Всегда из младшего керри можно стать старшим на нём"},{"k":"caption","t":"Опа Габен вернул, я открою и раздам людям кто у меня в друзьях"},{"k":"caption","t":"Вот такие скины есть, но могу дарить кто в друзьях у меня уже"},{"k":"post","t":"Пишите именно ники как вы в стиме подписаны, что бы я вас по поиску нашел, я уезжаю сейчас на заказ (надо отработать толпе бомжей), как вернусь раздам рандомно людям, из списка.\n\nВажно вы должны в друзьях быть не менее 30 дней!"},{"k":"caption","t":"Завтра оставшиеся подарю, я себе сделал списки людей"},{"k":"caption","t":"Вторая партия отправилась"},{"k":"caption","t":"Так давно мы с вами не ебались в жопу играли. Кто хочет поиграть?"},{"k":"caption","t":"Ну оракл тип прикольный, главное ебалом не щелкать, что бы ульту кинуть вовремя"},{"k":"caption","t":"Ну вот играем с подписчиками. Это мои мальчики. Все по моим гайдам"},{"k":"caption","t":"Обидно, что уже есть эта аркана"},{"k":"caption","t":"Пудж сюдааа"},{"k":"caption","t":"Это что за хуйня тут происходит...."},{"k":"caption","t":"Открыл обучение, нехуя не понял, закрыл игру"},{"k":"caption","t":"Оракл, один из легчайших саппортов для руина игры. Просто рандомно кидайте свои скиллы и фид вам гарантирован"}];
